// Aggregate metrics for a simple dashboard
function aggregateMetrics(testRuns, defects, timeData) {
    const metrics = {
        // Stability metrics
        totalTests: testRuns.length,
        passingTests: testRuns.filter(r => r.status === 'PASS').length,
        stabilityRate: (testRuns.filter(r => r.status === 'PASS').length / testRuns.length) * 100,

        // Quality metrics
        defectsFound: defects.filter(d => d.source === 'automation').length,
        productionDefects: defects.filter(d => d.environment === 'production').length,
        escapeRate: (defects.filter(d => d.environment === 'production').length / defects.length) * 100,

        // Efficiency metrics
        avgExecutionTime: timeData.reduce((sum, t) => sum + t.duration, 0) / timeData.length,
        feedbackTime: timeData.reduce((sum, t) => sum + t.feedbackTime, 0) / timeData.length
    };

    return metrics;
}

