def calculate_risk_score(failure_probability, business_impact, user_exposure):
    """Calculate risk score using weighted factors"""
    weights = {
        'failure_probability': 0.4,
        'business_impact': 0.4,
        'user_exposure': 0.2
    }

    risk_score = (
        failure_probability * weights['failure_probability'] +
        business_impact * weights['business_impact'] +
        user_exposure * weights['user_exposure']
    )

    # Categorize risk level
    if risk_score >= 0.8:
        risk_level = 'CRITICAL'
    elif risk_score >= 0.6:
        risk_level = 'HIGH'
    elif risk_score >= 0.4:
        risk_level = 'MEDIUM'
    else:
        risk_level = 'LOW'

    return risk_score, risk_level

