class TestSelector:
    def __init__(self, test_dependency_map):
        """
        test_dependency_map: Dictionary mapping tests to modules/functions they test
        """
        self.test_dependency_map = test_dependency_map
        self.inverse_map = self._build_inverse_map()

    def _build_inverse_map(self):
        """Build map from modules to tests that cover them"""
        inverse = {}
        for test, modules in self.test_dependency_map.items():
            for module in modules:
                if module not in inverse:
                    inverse[module] = []
                inverse[module].append(test)
        return inverse

    def select_tests_for_changes(self, changed_modules, risk_level='MEDIUM'):
        """Select tests affected by specific code changes"""
        directly_affected = set()
        for module in changed_modules:
            if module in self.inverse_map:
                directly_affected.update(self.inverse_map[module])

        # Return sorted by importance (you could add priority logic here)
        return sorted(list(directly_affected))

    def select_smart_suite(self, available_time, test_metadata):
        """Select optimal test suite given time constraints"""
        tests = []
        total_time = 0

        # Sort tests by value per time unit (defects caught per minute)
        prioritized_tests = sorted(
            test_metadata.items(),
            key=lambda x: x[1]['defects_per_minute'],
            reverse=True
        )

        for test_name, metadata in prioritized_tests:
            if total_time + metadata['avg_time'] <= available_time:
                tests.append(test_name)
                total_time += metadata['avg_time']
            else:
                break

        return tests, total_time

