class TestDataOptimizer:
    def __init__(self, test_requirements):
        self.test_requirements = test_requirements

    def analyze_data_patterns(self):
        """Analyze test data usage patterns"""
        data_usage = {}

        for test, requirements in self.test_requirements.items():
            for data_type in requirements.get('data_types', []):
                if data_type not in data_usage:
                    data_usage[data_type] = {'tests': [], 'setup_time': 0}
                data_usage[data_type]['tests'].append(test)
                data_usage[data_type]['setup_time'] += requirements.get('setup_time', 0)

        return data_usage

    def recommend_optimizations(self):
        """Recommend data management optimizations"""
        data_usage = self.analyze_data_patterns()
        recommendations = []

        for data_type, usage in data_usage.items():
            if len(usage['tests']) > 3:
                # Multiple tests use same data type - recommend pooling
                recommendations.append({
                    'type': 'DATA_POOLING',
                    'data_type': data_type,
                    'tests_affected': len(usage['tests']),
                    'time_savings': usage['setup_time'] * 0.7,  # Estimated 70% reduction
                    'description': f"Create shared {data_type} pool for {len(usage['tests'])} tests"
                })

            if usage['setup_time'] > 300:  # More than 5 minutes setup
                recommendations.append({
                    'type': 'SETUP_OPTIMIZATION',
                    'data_type': data_type,
                    'current_time': usage['setup_time'],
                    'description': f"Optimize {data_type} setup (currently {usage['setup_time']}s)"
                })

        return recommendations

