class OptimizationMetricsTracker:
    def __init__(self):
        self.metrics_history = []

    def record_metrics(self, timestamp, metrics):
        """Record optimization metrics"""
        self.metrics_history.append({
            'timestamp': timestamp,
            'metrics': metrics
        })

    def calculate_improvements(self, baseline_date, current_date):
        """Calculate improvements from baseline to current"""
        baseline = None
        current = None

        for entry in self.metrics_history:
            if entry['timestamp'] == baseline_date:
                baseline = entry['metrics']
            if entry['timestamp'] == current_date:
                current = entry['metrics']

        if not baseline or not current:
            return None

        improvements = {}
        for key in baseline.keys():
            if key in current and isinstance(baseline[key], (int, float)):
                if baseline[key] != 0:
                    improvement = ((current[key] - baseline[key]) / baseline[key]) * 100
                else:
                    improvement = 100 if current[key] > 0 else 0
                improvements[key] = improvement

        return improvements

