class QualityAlertSystem:
    def __init__(self, thresholds):
        self.thresholds = thresholds
        self.alert_history = []

    def check_metrics(self, current_metrics):
        """Check current metrics against thresholds"""
        alerts = []

        for metric_name, value in current_metrics.items():
            if metric_name in self.thresholds:
                threshold = self.thresholds[metric_name]

                if 'max' in threshold and value > threshold['max']:
                    severity = self._determine_severity(value, threshold['max'], 'max')
                    alerts.append({
                        'metric': metric_name,
                        'value': value,
                        'threshold': threshold['max'],
                        'direction': 'above',
                        'severity': severity,
                        'message': f"{metric_name} is {value} (threshold: {threshold['max']})"
                    })

                if 'min' in threshold and value < threshold['min']:
                    severity = self._determine_severity(value, threshold['min'], 'min')
                    alerts.append({
                        'metric': metric_name,
                        'value': value,
                        'threshold': threshold['min'],
                        'direction': 'below',
                        'severity': severity,
                        'message': f"{metric_name} is {value} (threshold: {threshold['min']})"
                    })

        return alerts

    def _determine_severity(self, value, threshold, direction):
        """Determine alert severity based on deviation"""
        if direction == 'max':
            deviation = (value - threshold) / threshold
        else:  # min
            deviation = (threshold - value) / threshold

        if deviation > 0.5:  # 50% deviation
            return 'CRITICAL'
        elif deviation > 0.2:  # 20% deviation
            return 'HIGH'
        elif deviation > 0.1:  # 10% deviation
            return 'MEDIUM'
        else:
            return 'LOW'

    def route_alerts(self, alerts, team_mapping):
        """Route alerts to appropriate teams"""
        routed = {}

        for alert in alerts:
            metric = alert['metric']
            team = team_mapping.get(metric, 'general')

            if team not in routed:
                routed[team] = []
            routed[team].append(alert)

            # Store in history
            self.alert_history.append({
                'timestamp': 'now',
                'alert': alert,
                'team': team
            })

        return routed

