class MetricsCollector:
    """Collect metrics from various sources"""

    def __init__(self, source_configs):
        self.source_configs = source_configs

    def collect_ci_metrics(self, ci_source):
        """Collect metrics from CI/CD system"""
        config = self.source_configs.get(ci_source, {})

        # In real implementation, this would call CI/CD API
        # Example metrics from Jenkins-like system
        metrics = {
            'build_success_rate': self._calculate_build_success_rate(config),
            'build_duration_avg': self._get_average_build_duration(config),
            'test_execution_time': self._get_test_execution_time(config),
            'pipeline_success_rate': self._calculate_pipeline_success(config)
        }

        return metrics

    def collect_test_metrics(self, test_source):
        """Collect metrics from test management system"""
        config = self.source_configs.get(test_source, {})

        metrics = {
            'test_coverage': self._calculate_test_coverage(config),
            'test_stability': self._calculate_test_stability(config),
            'defect_detection_rate': self._calculate_defect_detection(config),
            'automation_effectiveness': self._calculate_automation_effectiveness(config)
        }

        return metrics

    def collect_defect_metrics(self, defect_source):
        """Collect metrics from defect tracking system"""
        config = self.source_configs.get(defect_source, {})

        metrics = {
            'defect_escape_rate': self._calculate_defect_escape_rate(config),
            'defect_resolution_time': self._calculate_resolution_time(config),
            'defect_severity_distribution': self._get_severity_distribution(config),
            'defect_trend': self._calculate_defect_trend(config)
        }

        return metrics

    def aggregate_metrics(self):
        """Aggregate metrics from all sources"""
        all_metrics = {}

        # Collect from each source type
        for source_type, source_name in [('ci', 'jenkins'), ('test', 'testrail'), ('defect', 'jira')]:
            if source_type == 'ci':
                metrics = self.collect_ci_metrics(source_name)
            elif source_type == 'test':
                metrics = self.collect_test_metrics(source_name)
            else:  # defect
                metrics = self.collect_defect_metrics(source_name)

            all_metrics.update(metrics)

        # Calculate composite metrics
        all_metrics['quality_score'] = self._calculate_quality_score(all_metrics)
        all_metrics['release_readiness'] = self._calculate_release_readiness(all_metrics)

        return all_metrics

    # Helper methods (simplified for example)
    def _calculate_quality_score(self, metrics):
        """Calculate overall quality score"""
        weights = {
            'test_stability': 0.25,
            'defect_escape_rate': 0.25,
            'test_coverage': 0.20,
            'build_success_rate': 0.20,
            'defect_resolution_time': 0.10
        }

        score = 0
        for metric, weight in weights.items():
            if metric in metrics:
                # Normalize different metrics to 0-100 scale
                if metric == 'defect_escape_rate':
                    # Lower is better, so invert
                    normalized = (1 - metrics[metric]) * 100
                elif metric == 'defect_resolution_time':
                    # Convert days to score (shorter is better)
                    normalized = max(0, 100 - (metrics[metric] * 10))
                else:
                    normalized = metrics[metric] * 100

                score += normalized * weight

        return score / 100  # Return as 0-1 scale

