class MetricsVisualizer:
    """Generate visualizations for metrics data"""

    @staticmethod
    def generate_kpi_card(metric_name, value, target=None, trend=None):
        """Generate KPI card HTML/JSON structure"""
        status = MetricsVisualizer._determine_status(value, target)

        card = {
            'type': 'kpi_card',
            'metric': metric_name,
            'value': value,
            'formatted_value': MetricsVisualizer._format_value(value, metric_name),
            'status': status,
            'target': target,
            'trend': trend
        }

        return card

    @staticmethod
    def generate_trend_chart(metric_name, data_points, time_period='7d'):
        """Generate trend chart configuration"""
        chart = {
            'type': 'line_chart',
            'metric': metric_name,
            'data_points': data_points,
            'time_period': time_period,
            'options': {
                'show_target': True,
                'smooth_lines': True,
                'fill_area': False
            }
        }

        return chart

    @staticmethod
    def generate_comparison_chart(metric_name, categories, values):
        """Generate bar chart for comparisons"""
        chart = {
            'type': 'bar_chart',
            'metric': metric_name,
            'categories': categories,
            'values': values,
            'options': {
                'horizontal': len(categories) > 8,
                'stacked': False,
                'show_values': True
            }
        }

        return chart

    @staticmethod
    def _determine_status(value, target):
        """Determine status color based on value vs target"""
        if target is None:
            return 'neutral'

        # For metrics where higher is better (coverage, stability)
        if isinstance(target, dict) and 'min' in target:
            if value >= target['min']:
                return 'good'
            elif value >= target['min'] * 0.9:
                return 'warning'
            else:
                return 'critical'
        # For metrics where lower is better (defect rate)
        elif isinstance(target, dict) and 'max' in target:
            if value <= target['max']:
                return 'good'
            elif value <= target['max'] * 1.1:
                return 'warning'
            else:
                return 'critical'

        return 'neutral'

    @staticmethod
    def _format_value(value, metric_name):
        """Format value based on metric type"""
        if 'rate' in metric_name or 'percentage' in metric_name:
            return f"{value:.1%}"
        elif 'time' in metric_name:
            if value < 60:
                return f"{value:.0f}s"
            elif value < 3600:
                return f"{value/60:.0f}m"
            else:
                return f"{value/3600:.1f}h"
        else:
            return str(value)

