class GoalTracker:
    """Track progress against quality goals"""

    def __init__(self, baseline_metrics, industry_benchmarks=None):
        self.baseline = baseline_metrics
        self.benchmarks = industry_benchmarks or {}
        self.goals = {}
        self.progress_history = []

    def set_goal(self, metric_name, target_value, deadline, owner):
        """Set a new quality improvement goal"""
        self.goals[metric_name] = {
            'target': target_value,
            'deadline': deadline,
            'owner': owner,
            'baseline': self.baseline.get(metric_name),
            'created': 'now'
        }

        return self.goals[metric_name]

    def update_progress(self, metric_name, current_value):
        """Update progress toward goal"""
        if metric_name not in self.goals:
            return None

        goal = self.goals[metric_name]
        baseline = goal['baseline']
        target = goal['target']

        if baseline is None or target is None:
            progress = None
        else:
            # Calculate progress percentage (0-100)
            if target > baseline:  # Higher is better
                if current_value >= target:
                    progress = 100
                else:
                    progress = ((current_value - baseline) / (target - baseline)) * 100
            else:  # Lower is better
                if current_value <= target:
                    progress = 100
                else:
                    progress = ((baseline - current_value) / (baseline - target)) * 100

            progress = max(0, min(100, progress))

        progress_record = {
            'metric': metric_name,
            'current': current_value,
            'progress': progress,
            'date': 'now',
            'vs_baseline': ((current_value - baseline) / baseline * 100) if baseline else None
        }

        self.progress_history.append(progress_record)
        return progress_record

    def get_goal_status(self, metric_name):
        """Get current status of a goal"""
        if metric_name not in self.goals:
            return None

        goal = self.goals[metric_name]

        # Find most recent progress update
        recent_progress = None
        for record in reversed(self.progress_history):
            if record['metric'] == metric_name:
                recent_progress = record
                break

        status = {
            'goal': goal,
            'current_progress': recent_progress,
            'benchmark': self.benchmarks.get(metric_name),
            'on_track': self._check_if_on_track(goal, recent_progress)
        }

        return status

    def _check_if_on_track(self, goal, progress):
        """Check if goal is on track to meet deadline"""
        if not progress or progress['progress'] is None:
            return 'unknown'

        # Simple calculation: if we're more than halfway to deadline,
        # we should be more than halfway to goal
        days_elapsed = 30  # Simplified - would calculate from dates
        total_days = 90    # Simplified - would calculate from deadline

        if days_elapsed / total_days > progress['progress'] / 100:
            return 'behind'
        else:
            return 'on_track'

