class RiskBasedTestingFramework:
    def __init__(self):
        self.risk_matrix = {}
        self.test_plans = {}

    def assess_risk(self, feature_id, impact, probability):
        """Assess risk for a feature"""
        risk_score = impact * probability

        risk_level = 'LOW'
        if risk_score >= 0.8:
            risk_level = 'CRITICAL'
        elif risk_score >= 0.6:
            risk_level = 'HIGH'
        elif risk_score >= 0.4:
            risk_level = 'MEDIUM'

        self.risk_matrix[feature_id] = {
            'impact': impact,
            'probability': probability,
            'risk_score': risk_score,
            'risk_level': risk_level
        }

        return risk_level

    def create_test_plan(self, feature_id, risk_level):
        """Create test plan based on risk level"""
        test_strategies = {
            'CRITICAL': {
                'coverage': '100%',
                'depth': 'Exhaustive',
                'automation': '100%',
                'frequency': 'Daily',
                'review': 'Executive'
            },
            'HIGH': {
                'coverage': '90%',
                'depth': 'Comprehensive',
                'automation': '90%',
                'frequency': 'Weekly',
                'review': 'Management'
            },
            'MEDIUM': {
                'coverage': '70%',
                'depth': 'Moderate',
                'automation': '70%',
                'frequency': 'Monthly',
                'review': 'Team Lead'
            },
            'LOW': {
                'coverage': '50%',
                'depth': 'Basic',
                'automation': '50%',
                'frequency': 'Quarterly',
                'review': 'Self'
            }
        }

        self.test_plans[feature_id] = test_strategies[risk_level]
        return test_strategies[risk_level]

    def generate_compliance_report(self, test_results, audit_requirements):
        """Generate compliance report for auditors"""
        report = {
            'executive_summary': {},
            'compliance_status': {},
            'test_evidence': [],
            'risk_assessment': self.risk_matrix,
            'remediation_plan': {}
        }

        # Map test results to compliance requirements
        for requirement in audit_requirements:
            requirement_id = requirement['id']
            applicable_tests = self.map_tests_to_requirement(
                requirement_id, test_results
            )

            # Determine compliance status
            if all(t['status'] == 'PASS' for t in applicable_tests):
                status = 'COMPLIANT'
            elif any(t['status'] == 'FAIL' for t in applicable_tests):
                status = 'NON_COMPLIANT'
            else:
                status = 'PARTIALLY_COMPLIANT'

            report['compliance_status'][requirement_id] = {
                'status': status,
                'evidence': applicable_tests,
                'last_tested': max(t['timestamp'] for t in applicable_tests)
            }

            # Add to remediation plan if non-compliant
            if status == 'NON_COMPLIANT':
                report['remediation_plan'][requirement_id] = {
                    'issues': [t for t in applicable_tests if t['status'] == 'FAIL'],
                    'priority': 'HIGH' if requirement['critical'] else 'MEDIUM',
                    'deadline': self.calculate_remediation_deadline(requirement)
                }

        # Calculate overall compliance score
        total_requirements = len(report['compliance_status'])
        compliant_requirements = sum(
            1 for s in report['compliance_status'].values() 
            if s['status'] == 'COMPLIANT'
        )

        report['executive_summary']['compliance_score'] = \
            (compliant_requirements / total_requirements) * 100

        return report

    def map_tests_to_requirement(self, requirement_id, test_results):
        """Map test results to specific compliance requirements"""
        # This would typically use a tagging or metadata system
        # For simplicity, we'll filter by requirement in test metadata
        return [
            t for t in test_results 
            if requirement_id in t.get('compliance_requirements', [])
        ]

    def calculate_remediation_deadline(self, requirement):
        """Calculate remediation deadline based on requirement criticality"""
        from datetime import datetime, timedelta

        if requirement['critical']:
            return (datetime.now() + timedelta(days=14)).strftime('%Y-%m-%d')
        else:
            return (datetime.now() + timedelta(days=30)).strftime('%Y-%m-%d')

class StakeholderAnalyzer:
    def __init__(self):
        self.stakeholders = {}
        self.engagement_plans = {}

    def analyze_stakeholders(self, stakeholder_data):
        """Analyze stakeholders based on influence and attitude"""
        analysis = {
            'champions': [],      # High influence, positive attitude
            'supporters': [],     # Low influence, positive attitude
            'neutral': [],        # Medium influence, neutral attitude
            'resisters': [],      # High influence, negative attitude
            'blockers': []        # Low influence, negative attitude
        }

        for stakeholder in stakeholder_data:
            influence = stakeholder['influence_score']  # 1-5
            attitude = stakeholder['attitude_score']    # -2 to +2

            if influence >= 4:
                if attitude >= 1:
                    category = 'champions'
                elif attitude <= -1:
                    category = 'resisters'
                else:
                    category = 'neutral'
            else:
                if attitude >= 1:
                    category = 'supporters'
                elif attitude <= -1:
                    category = 'blockers'
                else:
                    category = 'neutral'

            stakeholder['category'] = category
            analysis[category].append(stakeholder)
            self.stakeholders[stakeholder['id']] = stakeholder

        return analysis

    def create_engagement_plans(self, stakeholder_analysis):
        """Create tailored engagement plans for each stakeholder category"""
        engagement_strategies = {
            'champions': {
                'engagement': 'Empower and leverage',
                'communication': 'Detailed technical updates, co-creation opportunities',
                'involvement': 'Lead pilot programs, speak at events, mentor others',
                'frequency': 'Weekly check-ins, continuous collaboration'
            },
            'supporters': {
                'engagement': 'Involve and recognize',
                'communication': 'Progress updates, success stories, recognition',
                'involvement': 'Participate in testing, provide feedback, share experiences',
                'frequency': 'Bi-weekly updates, monthly recognition'
            },
            'neutral': {
                'engagement': 'Educate and demonstrate value',
                'communication': 'Clear benefits, case studies, addressing concerns',
                'involvement': 'Information sessions, pilot observation, gradual involvement',
                'frequency': 'Monthly communications, quarterly workshops'
            },
            'resisters': {
                'engagement': 'Address concerns, build trust',
                'communication': 'One-on-one meetings, address specific concerns, show empathy',
                'involvement': 'Involve in planning, address their pain points, gradual exposure',
                'frequency': 'Bi-weekly meetings, continuous relationship building'
            },
            'blockers': {
                'engagement': 'Monitor and contain',
                'communication': 'Basic information, clear boundaries, factual updates',
                'involvement': 'Limited, with clear guidelines and supervision',
                'frequency': 'As needed, minimal but consistent'
            }
        }

        for category, stakeholders in stakeholder_analysis.items():
            for stakeholder in stakeholders:
                plan = engagement_strategies[category].copy()
                plan['stakeholder'] = stakeholder['name']
                plan['role'] = stakeholder['role']
                plan['key_concerns'] = stakeholder.get('concerns', [])

                self.engagement_plans[stakeholder['id']] = plan

        return self.engagement_plans

    def track_engagement_effectiveness(self, feedback_data):
        """Track effectiveness of engagement strategies"""
        effectiveness_report = {
            'engagement_metrics': {},
            'attitude_changes': {},
            'recommendations': []
        }

        for stakeholder_id, feedback in feedback_data.items():
            if stakeholder_id in self.stakeholders:
                stakeholder = self.stakeholders[stakeholder_id]
                previous_attitude = stakeholder['attitude_score']
                current_attitude = feedback.get('attitude_score', previous_attitude)

                attitude_change = current_attitude - previous_attitude

                effectiveness_report['attitude_changes'][stakeholder_id] = {
                    'previous': previous_attitude,
                    'current': current_attitude,
                    'change': attitude_change,
                    'effectiveness': 'positive' if attitude_change > 0 else 
                                    'negative' if attitude_change < 0 else 'neutral'
                }

                # Update stakeholder record
                self.stakeholders[stakeholder_id]['attitude_score'] = current_attitude

        # Generate recommendations based on patterns
        positive_changes = sum(1 for change in effectiveness_report['attitude_changes'].values() 
                             if change['effectiveness'] == 'positive')
        total_stakeholders = len(effectiveness_report['attitude_changes'])

        if total_stakeholders > 0:
            success_rate = (positive_changes / total_stakeholders) * 100

            if success_rate >= 70:
                effectiveness_report['recommendations'].append(
                    "Continue current engagement strategies, scale successful approaches"
                )
            elif success_rate >= 40:
                effectiveness_report['recommendations'].append(
                    "Review and adjust engagement plans for neutral and negative stakeholders"
                )
            else:
                effectiveness_report['recommendations'].append(
                    "Conduct root cause analysis of resistance, redesign engagement approach"
                )

        return effectiveness_report

