class CulturalTransformationMetrics:
    def __init__(self):
        self.baseline_metrics = {}
        self.ongoing_measurements = []
        self.cultural_dimensions = [
            'innovation_mindset',
            'collaboration_patterns', 
            'learning_orientation',
            'quality_ownership',
            'risk_tolerance'
        ]

    def establish_baseline(self, measurement_data):
        """Establish baseline cultural metrics"""
        self.baseline_metrics = {
            'timestamp': 'baseline_date',
            'dimension_scores': {},
            'qualitative_insights': [],
            'demographic_breakdown': {}
        }

        for dimension in self.cultural_dimensions:
            if dimension in measurement_data:
                score = measurement_data[dimension]['score']
                self.baseline_metrics['dimension_scores'][dimension] = score

        return self.baseline_metrics

    def measure_cultural_progress(self, current_data, measurement_period):
        """Measure current cultural state and progress from baseline"""
        current_measurement = {
            'period': measurement_period,
            'dimension_scores': {},
            'progress_from_baseline': {},
            'key_insights': []
        }

        # Calculate current scores
        for dimension in self.cultural_dimensions:
            if dimension in current_data:
                current_score = current_data[dimension]['score']
                baseline_score = self.baseline_metrics['dimension_scores'].get(dimension, 0)

                current_measurement['dimension_scores'][dimension] = current_score

                # Calculate progress
                if baseline_score != 0:
                    progress = ((current_score - baseline_score) / baseline_score) * 100
                else:
                    progress = 100 if current_score > 0 else 0

                current_measurement['progress_from_baseline'][dimension] = {
                    'baseline': baseline_score,
                    'current': current_score,
                    'absolute_change': current_score - baseline_score,
                    'percentage_change': progress
                }

                # Generate insights
                if progress >= 20:
                    current_measurement['key_insights'].append(
                        f"Significant improvement in {dimension.replace('_', ' ')}: +{progress:.1f}%"
                    )
                elif progress <= -10:
                    current_measurement['key_insights'].append(
                        f"Attention needed for {dimension.replace('_', ' ')}: {progress:.1f}% decline"
                    )

        self.ongoing_measurements.append(current_measurement)
        return current_measurement

    def analyze_cultural_patterns(self):
        """Analyze patterns and trends in cultural transformation"""
        if len(self.ongoing_measurements) < 2:
            return {"error": "Insufficient data for pattern analysis"}

        analysis = {
            'trend_analysis': {},
            'correlation_insights': [],
            'transformation_stage': 'initial',
            'recommendations': []
        }

        # Analyze trends for each dimension
        for dimension in self.cultural_dimensions:
            scores_over_time = []
            for measurement in self.ongoing_measurements:
                if dimension in measurement['dimension_scores']:
                    scores_over_time.append(measurement['dimension_scores'][dimension])

            if len(scores_over_time) >= 3:
                # Simple trend analysis
                first_half_avg = sum(scores_over_time[:len(scores_over_time)//2]) / (len(scores_over_time)//2)
                second_half_avg = sum(scores_over_time[len(scores_over_time)//2:]) / (len(scores_over_time)//2)

                trend = 'improving' if second_half_avg > first_half_avg else \
                       'declining' if second_half_avg < first_half_avg else 'stable'

                analysis['trend_analysis'][dimension] = {
                    'trend': trend,
                    'rate_of_change': (second_half_avg - first_half_avg) / first_half_avg * 100,
                    'consistency': 'high' if max(scores_over_time) - min(scores_over_time) < 0.5 else 'low'
                }

        # Determine transformation stage
        improving_dimensions = sum(1 for dim_analysis in analysis['trend_analysis'].values() 
                                 if dim_analysis['trend'] == 'improving')
        total_dimensions = len(analysis['trend_analysis'])

        if total_dimensions > 0:
            improvement_ratio = improving_dimensions / total_dimensions

            if improvement_ratio >= 0.8:
                analysis['transformation_stage'] = 'accelerating'
                analysis['recommendations'].append("Scale successful approaches, expand to new areas")
            elif improvement_ratio >= 0.5:
                analysis['transformation_stage'] = 'progressing'
                analysis['recommendations'].append("Double down on working strategies, address lagging areas")
            elif improvement_ratio >= 0.3:
                analysis['transformation_stage'] = 'emerging'
                analysis['recommendations'].append("Identify and amplify early successes, build momentum")
            else:
                analysis['transformation_stage'] = 'initiating'
                analysis['recommendations'].append("Focus on quick wins, build foundational support")

        return analysis

    def generate_cultural_transformation_report(self):
        """Generate comprehensive cultural transformation report"""
        latest_measurement = self.ongoing_measurements[-1] if self.ongoing_measurements else None
        pattern_analysis = self.analyze_cultural_patterns()

        report = {
            'executive_summary': {
                'current_state': pattern_analysis.get('transformation_stage', 'unknown'),
                'overall_progress': self.calculate_overall_progress(),
                'key_achievements': [],
                'critical_areas': []
            },
            'detailed_analysis': {
                'dimension_progress': latest_measurement.get('progress_from_baseline', {}) if latest_measurement else {},
                'trend_analysis': pattern_analysis.get('trend_analysis', {}),
                'key_insights': latest_measurement.get('key_insights', []) if latest_measurement else []
            },
            'recommendations': pattern_analysis.get('recommendations', []),
            'next_steps': self.generate_next_steps(pattern_analysis)
        }

        # Populate achievements and critical areas
        if latest_measurement:
            for dimension, progress in latest_measurement['progress_from_baseline'].items():
                if progress['percentage_change'] >= 15:
                    report['executive_summary']['key_achievements'].append(
                        f"{dimension.replace('_', ' ').title()}: {progress['percentage_change']:.1f}% improvement"
                    )
                elif progress['percentage_change'] <= -5:
                    report['executive_summary']['critical_areas'].append(
                        f"{dimension.replace('_', ' ').title()}: {progress['percentage_change']:.1f}% decline"
                    )

        return report

