class BusinessObjectiveMapper:
    def __init__(self):
        self.business_objectives = []
        self.automation_initiatives = []
        self.alignment_matrix = {}

    def map_initiatives_to_objectives(self, objectives, initiatives):
        """Map automation initiatives to business objectives with impact scoring"""
        alignment_matrix = {}

        for objective in objectives:
            objective_id = objective['id']
            alignment_matrix[objective_id] = {
                'objective': objective['description'],
                'priority': objective['priority'],
                'initiatives': [],
                'total_impact_score': 0
            }

            for initiative in initiatives:
                impact_score = self.calculate_impact_score(initiative, objective)
                if impact_score > 0:
                    alignment_entry = {
                        'initiative_id': initiative['id'],
                        'initiative_name': initiative['name'],
                        'impact_score': impact_score,
                        'impact_description': self.describe_impact(initiative, objective)
                    }
                    alignment_matrix[objective_id]['initiatives'].append(alignment_entry)
                    alignment_matrix[objective_id]['total_impact_score'] += impact_score

        self.alignment_matrix = alignment_matrix
        return alignment_matrix

    def calculate_impact_score(self, initiative, objective):
        """Calculate impact score based on multiple factors"""
        # Factor 1: Direct contribution (0-3)
        direct_contribution = initiative.get('contribution_to_objective', 0)

        # Factor 2: Time to value (faster = higher score)
        time_to_value = 3 - min(initiative.get('time_to_value_months', 12) // 3, 3)

        # Factor 3: Resource requirements (lower = higher score)
        resource_score = 3 - min(initiative.get('resource_intensity', 3) - 1, 3)

        # Factor 4: Risk level (lower = higher score)
        risk_score = 3 - initiative.get('risk_level', 2)

        # Weighted total
        total_score = (direct_contribution * 0.4 + 
                      time_to_value * 0.25 + 
                      resource_score * 0.2 + 
                      risk_score * 0.15)

        # Scale to 0-10
        return total_score * (10/3)

    def prioritize_initiatives(self):
        """Prioritize initiatives based on business objective alignment"""
        initiative_scores = {}

        for objective_id, objective_data in self.alignment_matrix.items():
            objective_priority = objective_data['priority']  # 1-5 scale

            for initiative in objective_data['initiatives']:
                initiative_id = initiative['initiative_id']

                if initiative_id not in initiative_scores:
                    initiative_scores[initiative_id] = {
                        'name': initiative['initiative_name'],
                        'total_score': 0,
                        'objectives_contributed': []
                    }

                # Weight impact by objective priority
                weighted_score = initiative['impact_score'] * objective_priority
                initiative_scores[initiative_id]['total_score'] += weighted_score
                initiative_scores[initiative_id]['objectives_contributed'].append({
                    'objective_id': objective_id,
                    'impact_score': initiative['impact_score']
                })

        # Sort initiatives by total score
        prioritized = sorted(
            initiative_scores.items(),
            key=lambda x: x[1]['total_score'],
            reverse=True
        )

        return prioritized

    def generate_strategy_report(self):
        """Generate strategic alignment report"""
        report = {
            'executive_summary': {
                'total_objectives': len(self.alignment_matrix),
                'total_initiatives': len(set(
                    i['initiative_id'] 
                    for obj in self.alignment_matrix.values() 
                    for i in obj['initiatives']
                )),
                'alignment_score': self.calculate_overall_alignment()
            },
            'objective_analysis': {},
            'initiative_prioritization': self.prioritize_initiatives()[:10],
            'recommendations': []
        }

        # Analyze each objective
        for obj_id, obj_data in self.alignment_matrix.items():
            report['objective_analysis'][obj_id] = {
                'objective': obj_data['objective'],
                'priority': obj_data['priority'],
                'initiative_count': len(obj_data['initiatives']),
                'total_impact': obj_data['total_impact_score'],
                'coverage_status': 'Well covered' if len(obj_data['initiatives']) >= 3 \
                                   else 'Partially covered' if len(obj_data['initiatives']) >= 1 \
                                   else 'Not covered'
            }

        # Generate recommendations
        well_covered = sum(1 for analysis in report['objective_analysis'].values() 
                          if analysis['coverage_status'] == 'Well covered')

        if well_covered / len(report['objective_analysis']) >= 0.7:
            report['recommendations'].append("Strong alignment achieved - focus on execution")
        else:
            report['recommendations'].append("Identify additional initiatives for under-covered objectives")

        return report

