class CapabilityMaturityAssessor:
    def __init__(self):
        self.capability_dimensions = [
            'strategy_governance',
            'people_skills',
            'process_methodology',
            'technology_tooling',
            'measurement_optimization'
        ]
        self.maturity_levels = {
            1: 'Initial',
            2: 'Repeatable',
            3: 'Defined',
            4: 'Managed',
            5: 'Optimizing'
        }

    def assess_maturity(self, assessment_data):
        """Assess maturity across capability dimensions"""
        maturity_scores = {}

        for dimension in self.capability_dimensions:
            if dimension in assessment_data:
                dimension_data = assessment_data[dimension]
                score = self.calculate_dimension_score(dimension_data)
                maturity_level = self.determine_maturity_level(score)

                maturity_scores[dimension] = {
                    'current_score': score,
                    'current_level': maturity_level,
                    'level_description': self.maturity_levels[maturity_level],
                    'assessment_criteria': dimension_data.get('criteria_met', []),
                    'gap_analysis': self.identify_gaps(dimension_data, maturity_level)
                }

        return maturity_scores

    def calculate_dimension_score(self, dimension_data):
        """Calculate maturity score for a dimension"""
        total_possible = len(dimension_data.get('assessment_criteria', []))
        met_criteria = len(dimension_data.get('criteria_met', []))

        if total_possible == 0:
            return 0

        # Convert to 1-5 scale
        base_score = (met_criteria / total_possible) * 5

        # Adjust for critical criteria
        critical_met = sum(1 for crit in dimension_data.get('criteria_met', []) 
                          if crit.get('critical', False))
        total_critical = sum(1 for crit in dimension_data.get('assessment_criteria', []) 
                            if crit.get('critical', False))

        if total_critical > 0:
            critical_score = (critical_met / total_critical) * 2  # Extra weight
            base_score = (base_score * 0.7) + (critical_score * 0.3)

        return min(5, max(1, base_score))

    def determine_maturity_level(self, score):
        """Determine maturity level from score"""
        if score >= 4.5:
            return 5
        elif score >= 3.5:
            return 4
        elif score >= 2.5:
            return 3
        elif score >= 1.5:
            return 2
        else:
            return 1

    def identify_gaps(self, dimension_data, current_level):
        """Identify gaps to reach next maturity level"""
        target_level = min(5, current_level + 1)
        gaps = []

        # Get criteria for target level
        target_criteria = self.get_level_criteria(target_level)
        current_criteria = set(crit['id'] for crit in dimension_data.get('criteria_met', []))

        for crit in target_criteria:
            if crit['id'] not in current_criteria:
                gaps.append({
                    'criteria_id': crit['id'],
                    'description': crit['description'],
                    'priority': 'High' if crit.get('critical', False) else 'Medium'
                })

        return gaps

    def create_maturity_roadmap(self, maturity_scores, target_maturity_level=4):
        """Create roadmap to reach target maturity level"""
        roadmap = {
            'current_state': {
                'overall_score': self.calculate_overall_score(maturity_scores),
                'dimension_details': maturity_scores
            },
            'target_state': {
                'target_level': target_maturity_level,
                'target_description': self.maturity_levels[target_maturity_level]
            },
            'improvement_initiatives': [],
            'timeline': {},
            'resource_requirements': {}
        }

        # Identify initiatives to close gaps
        for dimension, scores in maturity_scores.items():
            current_level = scores['current_level']

            if current_level < target_maturity_level:
                gaps = scores['gap_analysis']

                for gap in gaps:
                    initiative = {
                        'dimension': dimension,
                        'gap_description': gap['description'],
                        'priority': gap['priority'],
                        'estimated_effort': self.estimate_effort(dimension, gap),
                        'dependencies': self.identify_dependencies(dimension, gap)
                    }
                    roadmap['improvement_initiatives'].append(initiative)

        # Prioritize initiatives
        roadmap['improvement_initiatives'].sort(
            key=lambda x: (0 if x['priority'] == 'High' else 1, x['estimated_effort'])
        )

        # Create timeline (simplified)
        total_effort = sum(i['estimated_effort'] for i in roadmap['improvement_initiatives'])
        roadmap['timeline'] = {
            'estimated_duration_months': total_effort / 20,  # Assuming 20 person-days per month
            'phases': self.create_implementation_phases(roadmap['improvement_initiatives'])
        }

        return roadmap

