class AutomationRoadmapBuilder:
    def __init__(self):
        self.roadmap_phases = []
        self.dependencies = {}
        self.resource_requirements = {}

    def create_phased_roadmap(self, initiatives, timeframe_years=3):
        """Create a phased roadmap over multiple years"""
        # Group initiatives by quarter
        quarters = timeframe_years * 4
        roadmap = {
            'quarters': {},
            'yearly_themes': {},
            'key_milestones': [],
            'resource_forecast': {}
        }

        # Initialize quarters
        for q in range(1, quarters + 1):
            roadmap['quarters'][f'Q{(q-1)%4 + 1} Y{(q-1)//4 + 1}'] = {
                'initiatives': [],
                'objectives': [],
                'resource_requirements': {'people': 0, 'budget': 0},
                'dependencies': []
            }

        # Assign initiatives to quarters based on dependencies and effort
        scheduled_initiatives = set()
        current_quarter = 1

        while len(scheduled_initiatives) < len(initiatives) and current_quarter <= quarters:
            quarter_key = f'Q{(current_quarter-1)%4 + 1} Y{(current_quarter-1)//4 + 1}'
            quarter_capacity = self.calculate_quarter_capacity(current_quarter)

            # Find initiatives that can be scheduled this quarter
            for initiative in initiatives:
                if initiative['id'] in scheduled_initiatives:
                    continue

                # Check if dependencies are met
                dependencies_met = all(
                    dep in scheduled_initiatives 
                    for dep in initiative.get('dependencies', [])
                )

                if dependencies_met:
                    # Check if initiative fits in quarter capacity
                    if initiative['estimated_effort'] <= quarter_capacity['remaining_effort']:
                        # Schedule initiative
                        roadmap['quarters'][quarter_key]['initiatives'].append(initiative)
                        roadmap['quarters'][quarter_key]['resource_requirements']['people'] += \
                            initiative.get('people_required', 1)
                        roadmap['quarters'][quarter_key]['resource_requirements']['budget'] += \
                            initiative.get('budget_required', 0)

                        quarter_capacity['remaining_effort'] -= initiative['estimated_effort']
                        scheduled_initiatives.add(initiative['id'])

                        # Add to key milestones if marked as major
                        if initiative.get('major_milestone', False):
                            roadmap['key_milestones'].append({
                                'quarter': quarter_key,
                                'initiative': initiative['name'],
                                'description': initiative['description']
                            })

            current_quarter += 1

        # Define yearly themes
        for year in range(1, timeframe_years + 1):
            year_quarters = [f'Q{q} Y{year}' for q in range(1, 5)]
            year_initiatives = []
            for q_key in year_quarters:
                if q_key in roadmap['quarters']:
                    year_initiatives.extend(roadmap['quarters'][q_key]['initiatives'])

            theme = self.determine_yearly_theme(year, year_initiatives)
            roadmap['yearly_themes'][f'Year {year}'] = theme

        # Calculate resource forecast
        roadmap['resource_forecast'] = self.calculate_resource_forecast(roadmap['quarters'])

        return roadmap

    def calculate_quarter_capacity(self, quarter_number):
        """Calculate available capacity for a quarter"""
        # Base capacity (can be adjusted based on organization size, seasonality, etc.)
        base_capacity = 10  # person-months per quarter

        # Adjust for learning curve in early quarters
        if quarter_number <= 2:
            capacity = base_capacity * 0.7
        elif quarter_number <= 4:
            capacity = base_capacity * 0.85
        else:
            capacity = base_capacity

        return {
            'total_capacity': capacity,
            'remaining_effort': capacity
        }

    def determine_yearly_theme(self, year, initiatives):
        """Determine theme for each year based on initiatives"""
        themes_by_year = {
            1: 'Foundation Building',
            2: 'Scale and Integration',
            3: 'Optimization and Innovation'
        }

        # Count initiative types
        foundation_count = sum(1 for i in initiatives if i.get('type') == 'foundation')
        scaling_count = sum(1 for i in initiatives if i.get('type') == 'scaling')
        optimization_count = sum(1 for i in initiatives if i.get('type') == 'optimization')

        # Determine dominant type
        if year == 1 or foundation_count > max(scaling_count, optimization_count):
            return themes_by_year[1]
        elif year == 2 or scaling_count > max(foundation_count, optimization_count):
            return themes_by_year[2]
        else:
            return themes_by_year[3]

    def calculate_resource_forecast(self, quarters):
        """Calculate resource forecast across the roadmap"""
        forecast = {
            'total_people_months': 0,
            'total_budget': 0,
            'peak_resources': {'people': 0, 'budget': 0},
            'quarterly_trend': []
        }

        for quarter_key, quarter_data in quarters.items():
            people = quarter_data['resource_requirements']['people']
            budget = quarter_data['resource_requirements']['budget']

            forecast['total_people_months'] += people * 3  # 3 months per quarter
            forecast['total_budget'] += budget

            forecast['peak_resources']['people'] = max(
                forecast['peak_resources']['people'], 
                people
            )
            forecast['peak_resources']['budget'] = max(
                forecast['peak_resources']['budget'], 
                budget
            )

            forecast['quarterly_trend'].append({
                'quarter': quarter_key,
                'people': people,
                'budget': budget
            })

        return forecast

    def generate_roadmap_report(self, roadmap):
        """Generate comprehensive roadmap report"""
        report = {
            'executive_summary': {
                'timeframe': f"{len(roadmap['quarters'])//4} years",
                'total_initiatives': sum(
                    len(q['initiatives']) for q in roadmap['quarters'].values()
                ),
                'total_investment': roadmap['resource_forecast']['total_budget'],
                'yearly_themes': roadmap['yearly_themes']
            },
            'quarterly_breakdown': roadmap['quarters'],
            'key_milestones': roadmap['key_milestones'],
            'resource_requirements': roadmap['resource_forecast'],
            'risk_assessment': self.assess_roadmap_risks(roadmap),
            'success_metrics': self.define_success_metrics(roadmap)
        }

        return report

