class ProgressTracker:
    def __init__(self, roadmap):
        self.roadmap = roadmap
        self.progress_data = []
        self.value_metrics = {}

    def track_progress(self, quarter, initiative_id, status, actual_effort, actual_cost):
        """Track progress against roadmap"""
        progress_record = {
            'quarter': quarter,
            'initiative_id': initiative_id,
            'status': status,  # Not Started, In Progress, Completed, Delayed, Cancelled
            'actual_effort': actual_effort,
            'actual_cost': actual_cost,
            'timestamp': 'current_date',
            'issues': []
        }

        self.progress_data.append(progress_record)

        # Update roadmap status
        self.update_roadmap_status(quarter, initiative_id, status)

        return progress_record

    def calculate_roadmap_health(self):
        """Calculate overall roadmap health score"""
        if not self.progress_data:
            return {'health_score': 0, 'status': 'No data'}

        completed = sum(1 for p in self.progress_data if p['status'] == 'Completed')
        in_progress = sum(1 for p in self.progress_data if p['status'] == 'In Progress')
        delayed = sum(1 for p in self.progress_data if p['status'] == 'Delayed')
        total = len(self.progress_data)

        # Calculate health score (0-100)
        completion_rate = (completed / total) * 100 if total > 0 else 0
        delay_penalty = (delayed / total) * 30 if total > 0 else 0  # 30% penalty per delay

        health_score = max(0, completion_rate - delay_penalty)

        # Determine health status
        if health_score >= 80:
            status = 'Green'
        elif health_score >= 60:
            status = 'Yellow'
        else:
            status = 'Red'

        return {
            'health_score': health_score,
            'status': status,
            'metrics': {
                'completion_rate': completion_rate,
                'delay_rate': (delayed / total) * 100 if total > 0 else 0,
                'in_progress_rate': (in_progress / total) * 100 if total > 0 else 0
            }
        }

    def track_value_realization(self, initiative_id, business_metrics):
        """Track value realization for completed initiatives"""
        value_record = {
            'initiative_id': initiative_id,
            'metrics': business_metrics,
            'realized_value': self.calculate_realized_value(business_metrics),
            'timestamp': 'current_date',
            'validation_method': business_metrics.get('validation_method', 'Direct Measurement')
        }

        if initiative_id not in self.value_metrics:
            self.value_metrics[initiative_id] = []
        self.value_metrics[initiative_id].append(value_record)

        return value_record

    def calculate_realized_value(self, business_metrics):
        """Calculate realized value from business metrics"""
        # This would be customized based on specific value drivers
        value = 0

        # Example calculations
        if 'time_savings' in business_metrics:
            hourly_rate = business_metrics.get('hourly_rate', 50)
            value += business_metrics['time_savings'] * hourly_rate

        if 'defect_reduction' in business_metrics:
            cost_per_defect = business_metrics.get('cost_per_defect', 5000)
            value += business_metrics['defect_reduction'] * cost_per_defect

        if 'revenue_impact' in business_metrics:
            value += business_metrics['revenue_impact']

        return value

    def generate_strategic_alignment_report(self):
        """Generate report on strategic alignment and value delivery"""
        report = {
            'roadmap_health': self.calculate_roadmap_health(),
            'value_realization': {
                'total_realized_value': sum(
                    max((v['realized_value'] for v in values), default=0)
                    for values in self.value_metrics.values()
                ),
                'initiatives_with_value_data': len(self.value_metrics),
                'average_roi': self.calculate_average_roi()
            },
            'strategic_alignment': {
                'objectives_advanced': self.identify_objectives_advanced(),
                'capabilities_built': self.identify_capabilities_built(),
                'alignment_score': self.calculate_strategic_alignment_score()
            },
            'recommendations': self.generate_recommendations()
        }

        return report

