// TestConfig.java
@Configuration
@EnableConfigurationProperties
@ComponentScan("com.company.ecommerce.bdd")
@PropertySource({
    "classpath:config/application-${env:dev}.yml",
    "classpath:config/application-common.yml"
})
public class TestConfig {

    @Value("${browser.name:chrome}")
    private String browserName;

    @Value("${base.url:http://localhost:8080}")
    private String baseUrl;

    @Value("${headless.mode:false}")
    private boolean headlessMode;

    @Bean
    @Scope("cucumber-glue")
    public WebDriver webDriver() {
        WebDriver driver;
        switch (browserName.toLowerCase()) {
            case "firefox":
                driver = new FirefoxDriver(setupFirefoxOptions());
                break;
            case "edge":
                driver = new EdgeDriver(setupEdgeOptions());
                break;
            default:
                driver = new ChromeDriver(setupChromeOptions());
        }
        driver.manage().window().maximize();
        driver.manage().timeouts()
            .implicitlyWait(Duration.ofSeconds(10))
            .pageLoadTimeout(Duration.ofSeconds(30));
        return driver;
    }

    @Bean
    @Scope("cucumber-glue")
    public TestContext testContext() {
        return new TestContext();
    }

    @Bean
    @Scope("cucumber-glue")
    public ApiService apiService() {
        return new ApiService(baseUrl + "/api");
    }

    @Bean
    public ObjectMapper objectMapper() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(new JavaTimeModule());
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
        return mapper;
    }

    private ChromeOptions setupChromeOptions() {
        ChromeOptions options = new ChromeOptions();
        if (headlessMode) {
            options.addArguments("--headless");
        }
        options.addArguments(
            "--no-sandbox",
            "--disable-dev-shm-usage",
            "--disable-gpu",
            "--window-size=1920,1080"
        );
        return options;
    }
}

