public abstract class BasePage {

    protected WebDriver driver;
    protected WebDriverWait wait;
    protected JavascriptExecutor js;
    protected TestContext testContext;

    @Autowired
    public BasePage(TestContext testContext) {
        this.testContext = testContext;
        this.driver = testContext.getDriver();
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(15));
        this.js = (JavascriptExecutor) driver;
    }

    protected void waitForPageLoad() {
        wait.until(d -> js.executeScript("return document.readyState").equals("complete"));
    }

    protected WebElement waitForElement(By locator) {
        return wait.until(ExpectedConditions.presenceOfElementLocated(locator));
    }

    protected WebElement waitForVisible(By locator) {
        return wait.until(ExpectedConditions.visibilityOfElementLocated(locator));
    }

    protected void clickWithRetry(By locator, int maxAttempts) {
        int attempts = 0;
        while (attempts < maxAttempts) {
            try {
                waitForVisible(locator).click();
                return;
            } catch (StaleElementReferenceException | ElementClickInterceptedException e) {
                attempts++;
                if (attempts == maxAttempts) throw e;
                waitForMillis(500);
            }
        }
    }

    protected void selectFromDropdown(By dropdownLocator, String value) {
        WebElement dropdown = waitForVisible(dropdownLocator);
        dropdown.click();
        By optionLocator = By.xpath(String.format(".//option[normalize-space()='%s']", value));
        waitForVisible(optionLocator).click();
    }

    protected void waitForMillis(long milliseconds) {
        try {
            Thread.sleep(milliseconds);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void takeScreenshot(String screenshotName) {
        testContext.attachScreenshot(screenshotName);
    }
}

@Component
@Scope("cucumber-glue")
public class CheckoutPage extends BasePage {

    // Locators
    private final By shippingAddressForm = By.id("shipping-address-form");
    private final By paymentMethodSelect = By.id("payment-method");
    private final By creditCardNumberInput = By.id("credit-card-number");
    private final By placeOrderButton = By.id("place-order-button");
    private final By orderConfirmation = By.className("order-confirmation");
    private final By orderNumber = By.className("order-number");

    @Autowired
    public CheckoutPage(TestContext testContext) {
        super(testContext);
    }

    public void proceedToCheckout() {
        waitForPageLoad();
        waitForVisible(By.id("checkout-button")).click();
        waitForVisible(shippingAddressForm);
    }

    public void selectPaymentMethod(String method) {
        selectFromDropdown(paymentMethodSelect, method);
    }

    public void enterCreditCardDetails(CreditCard card) {
        waitForVisible(creditCardNumberInput).sendKeys(card.getNumber());
        driver.findElement(By.id("expiry-date")).sendKeys(card.getExpiry());
        driver.findElement(By.id("cvv")).sendKeys(card.getCvv());
        driver.findElement(By.id("cardholder-name")).sendKeys(card.getName());
    }

    public Order placeOrder() {
        clickWithRetry(placeOrderButton, 3);
        waitForVisible(orderConfirmation);

        String orderNumberText = waitForVisible(orderNumber).getText();
        String totalAmount = driver.findElement(By.className("order-total")).getText();

        Order order = new Order();
        order.setOrderNumber(orderNumberText);
        order.setTotalAmount(parseCurrency(totalAmount));
        order.setStatus("CONFIRMED");

        testContext.put(TestContext.ContextKey.CURRENT_ORDER, order);
        return order;
    }

    public boolean isErrorMessageDisplayed(String expectedError) {
        try {
            WebElement errorElement = wait.until(ExpectedConditions
                .presenceOfElementLocated(By.xpath(
                    String.format("//*[contains(text(), '%s')]", expectedError)
                )));
            return errorElement.isDisplayed();
        } catch (TimeoutException e) {
            return false;
        }
    }

    private BigDecimal parseCurrency(String amount) {
        String cleanAmount = amount.replaceAll("[^\\d.]", "");
        return new BigDecimal(cleanAmount);
    }
}

