    @Given("I have items in my cart")
    public void i_have_items_in_cart(DataTable dataTable) {
        List<Map<String, String>> items = dataTable.asMaps();
        List<CartItem> cartItems = items.stream()
            .map(item -> new CartItem(
                item.get("Product"),
                Integer.parseInt(item.get("Quantity")),
                new BigDecimal(item.get("Price"))
            ))
            .collect(Collectors.toList());

        // Add items via API for faster setup
        cartItems.forEach(item -> 
            apiService.addToCart(testContext.get(TestContext.ContextKey.CURRENT_USER), item)
        );

        testContext.put(TestContext.ContextKey.TEST_DATA, cartItems);
    }

    @Given("I proceed to checkout")
    public void i_proceed_to_checkout() {
        checkoutPage.proceedToCheckout();
    }

    @When("I select {string} as payment method")
    public void i_select_as_payment_method(String paymentMethod) {
        checkoutPage.selectPaymentMethod(paymentMethod);
    }

    @When("I enter valid credit card details:")
    public void i_enter_valid_credit_card_details(DataTable dataTable) {
        Map<String, String> cardDetails = dataTable.asMap();
        CreditCard card = new CreditCard(
            cardDetails.get("Card Number"),
            cardDetails.get("Expiry"),
            cardDetails.get("CVV"),
            cardDetails.get("Name on Card")
        );
        checkoutPage.enterCreditCardDetails(card);
    }

    @When("I click {string}")
    public void i_click(String buttonText) {
        checkoutPage.clickWithRetry(
            By.xpath(String.format("//button[normalize-space()='%s']", buttonText)),
            3
        );
    }

    @Then("my order should be confirmed with number matching pattern {string}")
    public void my_order_should_be_confirmed(String pattern) {
        Order order = checkoutPage.placeOrder();
        assertThat(order.getOrderNumber()).matches(pattern);

        // Verify via API
        Order apiOrder = apiService.getOrder(order.getOrderNumber());
        assertThat(apiOrder.getStatus()).isEqualTo("CONFIRMED");

        testContext.put(TestContext.ContextKey.CURRENT_ORDER, order);
    }

    @Then("I should receive order confirmation email within {int} minutes")
    public void should_receive_email_within_minutes(int minutes) {
        String email = testContext.get(TestContext.ContextKey.CURRENT_USER).getEmail();

        // Poll email service
        await().atMost(minutes, TimeUnit.MINUTES)
               .pollInterval(30, TimeUnit.SECONDS)
               .until(() -> emailService.hasConfirmationEmail(email));
    }

