    public void inventory_should_be_reserved() {
        Order order = testContext.get(TestContext.ContextKey.CURRENT_ORDER);
        List<CartItem> orderedItems = testContext.get(TestContext.ContextKey.TEST_DATA);

        orderedItems.forEach(item -> {
            ProductInventory inventory = apiService.getInventory(item.getProductId());
            assertThat(inventory.getReservedQuantity()).isGreaterThan(0);
        });
