    // Complex data table processing
    @Given("I have the following items in my cart:")
    public void have_following_items_in_cart(DataTable dataTable) {
        List<Map<String, String>> rows = dataTable.asMaps();

        for (Map<String, String> row : rows) {
            String product = row.get("Product");
            int quantity = Integer.parseInt(row.get("Quantity"));
            String notes = row.get("Notes"); // Optional column

            // Add item with optional notes
            apiService.addToCartWithNotes(product, quantity, notes);
        }
    }

