    @ParameterType("\\d+\\\\.\\d{2}")
    public Money money(String value) {
        return new Money(new BigDecimal(value));
    }

    @Then("cart total should be {money}")
    public void cart_total_should_be(Money expectedTotal) {
        Money actualTotal = checkoutPage.getCartTotal();
        assertThat(actualTotal).isEqualTo(expectedTotal);
    }
