// cucumber.ts - Main configuration
import { Before, After, BeforeAll, AfterAll, Status, setDefaultTimeout } from '@cucumber/cucumber';
import { Browser, BrowserContext, Page, chromium } from 'playwright';
import * as path from 'path';

// Set default timeout for all steps (30 seconds)
setDefaultTimeout(30 * 1000);

// Global variables for sharing between hooks and steps
export let browser: Browser;
export let context: BrowserContext;
export let page: Page;
export const testContext: TestContext = new TestContext();

// Test context for sharing data between steps
class TestContext {
  private data: Map<string, any> = new Map();
  private screenshots: string[] = [];

  set(key: string, value: any): void {
    this.data.set(key, value);
  }

  get<T>(key: string): T {
    return this.data.get(key);
  }

  addScreenshot(filepath: string): void {
    this.screenshots.push(filepath);
  }

  getScreenshots(): string[] {
    return [...this.screenshots];
  }

  clear(): void {
    this.data.clear();
    this.screenshots = [];
  }
}

// Hooks
BeforeAll(async function () {
  console.log('Starting test suite...');

  // Load environment configuration
  const env = process.env.TEST_ENV || 'development';
  const config = await loadConfig(env);
  testContext.set('config', config);

  // Initialize browser (headless in CI)
  const launchOptions: any = {
    headless: process.env.CI === 'true',
    args: ['--no-sandbox', '--disable-dev-shm-usage']
  };

  browser = await chromium.launch(launchOptions);
});

Before(async function (scenario) {
  console.log(`Starting scenario: ${scenario.pickle.name}`);

  // Create new context and page for each scenario
  context = await browser.newContext({
    viewport: { width: 1920, height: 1080 },
    locale: 'en-US',
    timezoneId: 'America/New_York'
  });

  page = await context.newPage();
  testContext.set('page', page);

  // Set scenario in context for reporting
  testContext.set('currentScenario', scenario);
});

After(async function (scenario) {
  console.log(`Finished scenario: ${scenario.pickle.name} - Status: ${scenario.result?.status}`);

  // Take screenshot on failure
  if (scenario.result?.status === Status.FAILED) {
    const screenshotPath = path.join(
      'test-results',
      'screenshots',
      `${scenario.pickle.name.replace(/[^a-z0-9]/gi, '_')}_${Date.now()}.png`
    );

    await page.screenshot({ path: screenshotPath, fullPage: true });
    testContext.addScreenshot(screenshotPath);

    // Attach screenshot to report
    this.attach(
      await page.screenshot(),
      'image/png'
    );

    // Attach page source for debugging
    this.attach(
      await page.content(),
      'text/html'
    );
  }

  // Cleanup
  await page.close();
  await context.close();
  testContext.clear();
});

AfterAll(async function () {
  console.log('Test suite completed');

  if (browser) {
    await browser.close();
  }
});

// Helper function to load configuration
async function loadConfig(env: string): Promise<any> {
  const configPath = path.join(__dirname, 'config', `${env}.json`);

  try {
    const config = await import(configPath);
    return config.default || config;
  } catch (error) {
    console.warn(`Config file not found: ${configPath}, using defaults`);
    return {
      baseUrl: 'http://localhost:3000',
      apiUrl: 'http://localhost:8080/api',
      timeout: 30000
    };
  }
}

