// BasePage.ts
abstract class BasePage {
  protected page: Page;
  protected baseUrl: string;

  constructor(page: Page) {
    this.page = page;
    this.baseUrl = testContext.get('config').baseUrl;
  }

  abstract getPath(): string;

  async navigate(): Promise<void> {
    const url = `${this.baseUrl}${this.getPath()}`;
    await this.page.goto(url);
    await this.waitForLoad();
  }

  async waitForLoad(): Promise<void> {
    await this.page.waitForLoadState('networkidle');
    await this.page.waitForTimeout(500); // Additional wait for animations
  }

  async getTitle(): Promise<string> {
    return await this.page.title();
  }

  async takeScreenshot(name: string): Promise<Buffer> {
    return await this.page.screenshot({ fullPage: true });
  }
}

// LoginPage.ts
class LoginPage extends BasePage {
  private selectors = {
    emailInput: '#email',
    passwordInput: '#password',
    submitButton: 'button[type="submit"]',
    errorMessage: '.error-message',
    forgotPasswordLink: 'a[href="/forgot-password"]'
  };

  getPath(): string {
    return '/login';
  }

  async login(email: string, password: string): Promise<void> {
    await this.page.fill(this.selectors.emailInput, email);
    await this.page.fill(this.selectors.passwordInput, password);
    await this.page.click(this.selectors.submitButton);
    await this.page.waitForLoadState('networkidle');
  }

  async getErrorMessage(): Promise<string> {
    return await this.page.textContent(this.selectors.errorMessage) || '';
  }

  async isErrorMessageVisible(): Promise<boolean> {
    return await this.page.isVisible(this.selectors.errorMessage);
  }
}

// ShoppingCartPage.ts
class ShoppingCartPage extends BasePage {
  private selectors = {
    cartItems: '.cart-item',
    itemName: '.item-name',
    itemQuantity: '.item-quantity input',
    itemPrice: '.item-price',
    cartSubtotal: '.cart-subtotal',
    cartTotal: '.cart-total',
    emptyCartMessage: '.empty-cart-message',
    removeItemButton: '.remove-item',
    updateCartButton: 'button:has-text("Update Cart")',
    checkoutButton: 'button:has-text("Checkout")'
  };

  getPath(): string {
    return '/cart';
  }

  async getItemCount(): Promise<number> {
    return await this.page.locator(this.selectors.cartItems).count();
  }

  async getItemNames(): Promise<string[]> {
    const items = await this.page.locator(this.selectors.itemName).allTextContents();
    return items.map(name => name.trim());
  }

  async updateQuantity(itemName: string, newQuantity: number): Promise<void> {
    const itemIndex = await this.getItemIndex(itemName);
    if (itemIndex === -1) {
      throw new Error(`Item ${itemName} not found in cart`);
    }

    const quantityInput = this.page.locator(this.selectors.itemQuantity).nth(itemIndex);
    await quantityInput.fill(newQuantity.toString());
  }

  async removeItem(itemName: string): Promise<void> {
    const itemIndex = await this.getItemIndex(itemName);
    if (itemIndex === -1) {
      throw new Error(`Item ${itemName} not found in cart`);
    }

    const removeButton = this.page.locator(this.selectors.removeItemButton).nth(itemIndex);
    await removeButton.click();
    await this.page.waitForLoadState('networkidle');
  }

  async getSubtotal(): Promise<number> {
    const subtotalText = await this.page.textContent(this.selectors.cartSubtotal);
    return this.parseCurrency(subtotalText || '0');
  }

  async getTotal(): Promise<number> {
    const totalText = await this.page.textContent(this.selectors.cartTotal);
    return this.parseCurrency(totalText || '0');
  }

  private async getItemIndex(itemName: string): Promise<number> {
    const itemNames = await this.getItemNames();
    return itemNames.indexOf(itemName);
  }

  private parseCurrency(currencyString: string): number {
    // Remove currency symbols and commas, then parse to number
    return parseFloat(currencyString.replace(/[^0-9.-]+/g, ''));
  }
}

