// visual-testing-framework.js
// Comprehensive visual testing framework supporting multiple tools

class VisualTestingFramework {
  constructor(config) {
    this.config = {
      defaultTool: 'applitools',
      parallelExecution: true,
      retryAttempts: 2,
      viewports: [
        { width: 1920, height: 1080, name: 'desktop_large' },
        { width: 1366, height: 768, name: 'desktop_medium' },
        { width: 768, height: 1024, name: 'tablet_portrait' },
        { width: 375, height: 667, name: 'mobile' }
      ],
      matchLevel: 'Layout',
      ...config
    };

    this.tools = {};
    this.results = [];
    this.initializeTools();
  }

  initializeTools() {
    // Initialize selected tools based on configuration
    if (this.config.tools.includes('applitools')) {
      this.tools.applitools = this.setupApplitools();
    }

    if (this.config.tools.includes('percy')) {
      this.tools.percy = this.setupPercy();
    }

    if (this.config.tools.includes('chromatic')) {
      this.tools.chromatic = this.setupChromatic();
    }

    // Initialize custom comparison for fallback
    this.tools.custom = this.setupCustomComparator();
  }

  setupApplitools() {
    const { Eyes, ClassicRunner, BatchInfo, RectangleSize } = require('@applitools/eyes-webdriverio');

    const eyes = new Eyes(new ClassicRunner());
    const batchInfo = new BatchInfo({
      name: this.config.batchName || `Visual Tests ${new Date().toISOString().split('T')[0]}`,
      id: process.env.CI_COMMIT_SHA || `local-${Date.now()}`,
      notifyOnCompletion: true,
      properties: [
        { name: 'Project', value: this.config.projectName },
        { name: 'Environment', value: process.env.NODE_ENV || 'development' }
      ]
    });

    eyes.setBatch(batchInfo);

    // Advanced configuration
    const configuration = eyes.getConfiguration();
    configuration.setAppName(this.config.appName);
    configuration.setTestName(this.config.testName);
    configuration.setViewportSize(new RectangleSize(this.config.viewports[0].width, this.config.viewports[0].height));
    configuration.setMatchLevel(this.config.matchLevel);
    configuration.setIgnoreDisplacements(true);
    configuration.setSaveNewTests(false);
    configuration.setSaveFailedTests(true);
    configuration.setSaveDiffs(true);
    configuration.setSendDom(true); // Enable DOM capture for better comparisons
    configuration.setEnablePatterns(true); // Enable pattern matching

    // Configure multiple browsers for cross-browser testing
    if (this.config.browsers && this.config.browsers.length > 0) {
      configuration.setBrowsers(this.config.browsers.map(browser => ({
        width: browser.width,
        height: browser.height,
        name: browser.name
      })));
    }

    // Configure accessibility validation
    if (this.config.accessibilityValidation) {
      configuration.setAccessibilityValidation({
        level: this.config.accessibilityValidation.level || 'AA',
        guidelinesVersion: 'WCAG_2_1'
      });
    }

    eyes.setConfiguration(configuration);

    // Set API key from environment variable
    if (process.env.APPLITOOLS_API_KEY) {
      eyes.setApiKey(process.env.APPLITOOLS_API_KEY);
    } else {
      console.warn('APPLITOOLS_API_KEY not set. Applitools tests will run in read-only mode.');
    }

    return {
      instance: eyes,
      runner: eyes.runner,
      async testPage(browser, url, testName, options = {}) {
        try {
          await eyes.open(browser, this.config.appName, testName);
          await browser.url(url);

          // Wait for page stability
          await this.waitForPageStability(browser, options.waitForSelectors);

          // Configure target based on options
          let target = eyes.Target.window()
            .fully(options.fullPage !== false)
            .layout()
            .ignoreCaret(true)
            .matchLevel(options.matchLevel || this.config.matchLevel);

          // Add ignore regions
          if (options.ignoreRegions && options.ignoreRegions.length > 0) {
            target = target.ignoreRegions(...options.ignoreRegions.map(selector => 
              eyes.Target.regionBySelector(selector)
            ));
          }

          // Add floating regions
          if (options.floatingRegions && options.floatingRegions.length > 0) {
            options.floatingRegions.forEach(region => {
              target = target.floatingRegion(
                eyes.Target.regionBySelector(region.selector),
                region.maxUpOffset,
                region.maxDownOffset,
                region.maxLeftOffset,
                region.maxRightOffset
              );
            });
          }

          // Add accessibility regions
          if (options.accessibilityRegions && options.accessibilityRegions.length > 0) {
            options.accessibilityRegions.forEach(region => {
              target = target.accessibilityRegion(
                eyes.Target.regionBySelector(region.selector),
                region.type || 'RegularText'
              );
            });
          }

          // Capture screenshot
          await eyes.check(testName, target);

          // Close and get results
          const results = await eyes.close(false);
          return this.processApplitoolsResults(results);

        } catch (error) {
          await eyes.abort();
          throw new Error(`Applitools test failed: ${error.message}`);
        }
      },

      async testResponsive(browser, url, testName) {
        const results = [];

        for (const viewport of this.config.viewports) {
          await browser.setWindowSize(viewport.width, viewport.height);
          await browser.pause(1000); // Allow for resize effects

          const viewportTestName = `${testName} - ${viewport.name}`;
          const result = await this.testPage(browser, url, viewportTestName);
          results.push({
            viewport,
            ...result
          });
        }

        return results;
      }
    };
  }

  setupPercy() {
    // Percy typically auto-configures from environment variables
    // PERCY_TOKEN, PERCY_BRANCH, PERCY_COMMIT

    return {
      async snapshot(page, name, options = {}) {
        const percySnapshot = require('@percy/webdriverio');

        const snapshotOptions = {
          widths: options.widths || this.config.viewports.map(v => v.width),
          minHeight: options.minHeight || 1024,
          enableJavaScript: options.enableJavaScript !== false,
          percyCSS: options.percyCSS || '',
          scope: options.scope ? `#${options.scope}` : null
        };

        try {
          await percySnapshot(page, name, snapshotOptions);
          return { status: 'success', tool: 'percy' };
        } catch (error) {
          return { 
            status: 'failed', 
            tool: 'percy',
            error: error.message 
          };
        }
      }
    };
  }

  setupCustomComparator() {
    // Custom pixel comparison using resemble.js
    const resemble = require('resemblejs');
    const fs = require('fs').promises;
    const path = require('path');

    return {
      async compare(baselinePath, currentPath, options = {}) {
        return new Promise((resolve, reject) => {
          resemble(baselinePath)
            .compareTo(currentPath)
            .ignoreColors(options.ignoreColors || false)
            .ignoreAntialiasing(options.ignoreAntialiasing || true)
            .ignoreLess(options.ignoreLess || false)
            .scaleToSameSize(options.scaleToSameSize || true)
            .onComplete(data => {
              resolve({
                isSameDimensions: data.isSameDimensions,
                dimensionDifference: data.dimensionDifference,
                rawMisMatchPercentage: data.rawMisMatchPercentage,
                misMatchPercentage: data.misMatchPercentage,
                diffBounds: data.diffBounds,
                analysisTime: data.analysisTime,
                diffImage: data.getImageDataUrl()
              });
            });
        });
      },

      async compareWithThreshold(baselinePath, currentPath, threshold = 0.1) {
        const result = await this.compare(baselinePath, currentPath);
        return {
          passed: result.misMatchPercentage <= threshold,
          mismatchPercentage: result.misMatchPercentage,
          ...result
        };
      }
    };
  }

  async testWithMultipleTools(browser, url, testName, options = {}) {
    const results = {
      testName,
      url,
      timestamp: new Date().toISOString(),
      tools: {}
    };

    // Run tests with each configured tool
    if (this.tools.applitools && options.useApplitools !== false) {
      try {
        results.tools.applitools = await this.tools.applitools.testPage(browser, url, testName, options);
      } catch (error) {
        results.tools.applitools = { error: error.message, status: 'failed' };
      }
    }

    if (this.tools.percy && options.usePercy !== false) {
      try {
        results.tools.percy = await this.tools.percy.snapshot(browser, testName, options.percyOptions);
      } catch (error) {
        results.tools.percy = { error: error.message, status: 'failed' };
      }
    }

    // Always run custom comparison as fallback
    if (this.tools.custom && options.saveScreenshots) {
      try {
        const baselineDir = path.join(__dirname, 'visual-baselines');
        const currentDir = path.join(__dirname, 'visual-current');

        await fs.mkdir(baselineDir, { recursive: true });
        await fs.mkdir(currentDir, { recursive: true });

        const safeTestName = testName.replace(/[^a-z0-9]/gi, '_').toLowerCase();
        const baselinePath = path.join(baselineDir, `${safeTestName}.png`);
        const currentPath = path.join(currentDir, `${safeTestName}_${Date.now()}.png`);

        // Take screenshot
        await browser.saveScreenshot(currentPath);

        // Compare if baseline exists
        if (await this.fileExists(baselinePath)) {
          results.tools.custom = await this.tools.custom.compareWithThreshold(
            baselinePath, 
            currentPath, 
            options.customThreshold || 0.5
          );
        } else {
          // Save as new baseline
          await fs.copyFile(currentPath, baselinePath);
          results.tools.custom = { status: 'new_baseline_created', baselinePath };
        }
      } catch (error) {
        results.tools.custom = { error: error.message, status: 'failed' };
      }
    }

    this.results.push(results);
    return results;
  }

  async waitForPageStability(browser, selectors = [], timeout = 30000) {
    const startTime = Date.now();

    // Wait for network idle
    await browser.waitUntil(
      async () => {
        const readyState = await browser.execute(() => document.readyState);
        return readyState === 'complete';
      },
      { timeout, timeoutMsg: 'Page failed to load within timeout' }
    );

    // Wait for specific selectors to be stable
    for (const selector of selectors) {
      try {
        const element = await browser.$(selector);
        await element.waitForExist({ timeout: 10000 });
        await element.waitForDisplayed({ timeout: 10000 });

        // Wait for element to be stable (not animating)
        await this.waitForElementStability(element, 2000);
      } catch (error) {
        console.warn(`Selector ${selector} not stable: ${error.message}`);
      }
    }

    // Additional wait for any CSS animations/transitions
    await browser.pause(1000);
  }

  async waitForElementStability(element, stabilityTime = 2000) {
    let previousRect = null;
    let stableStart = Date.now();

    while (Date.now() - stableStart < stabilityTime) {
      const currentRect = await element.getLocation();

      if (previousRect && 
          (currentRect.x !== previousRect.x || currentRect.y !== previousRect.y)) {
        // Element moved, reset stability timer
        stableStart = Date.now();
      }

      previousRect = currentRect;
      await browser.pause(100);
    }
  }

  async fileExists(filePath) {
    try {
      await fs.access(filePath);
      return true;
    } catch {
      return false;
    }
  }

  processApplitoolsResults(results) {
    return {
      status: results.getStatus(),
      url: results.getUrl(),
      steps: results.getStepsInfo().map(step => ({
        name: step.getName(),
        hasDiff: step.getHasDiff(),
        diffUrl: step.getAppUrls().getDiff(),
        baselineUrl: step.getAppUrls().getBaseline(),
        checkpointUrl: step.getAppUrls().getCheckpoint()
      })),
      differences: results.getStepsInfo().filter(step => step.getHasDiff()).length,
      newTests: results.getStepsInfo().filter(step => step.getIsNew()).length,
      unresolvedTests: results.getStepsInfo().filter(step => step.getIsDifferent()).length
    };
  }

  generateReport() {
    const report = {
      summary: {
        totalTests: this.results.length,
        passed: 0,
        failed: 0,
        newBaselines: 0,
        unresolved: 0,
        toolBreakdown: {}
      },
      details: this.results,
      metadata: {
        generatedAt: new Date().toISOString(),
        environment: process.env.NODE_ENV || 'development',
        commitSha: process.env.CI_COMMIT_SHA || 'local',
        branch: process.env.CI_COMMIT_REF_NAME || 'local'
      }
    };

    // Calculate statistics
    for (const result of this.results) {
      if (result.tools.applitools) {
        if (!report.summary.toolBreakdown.applitools) {
          report.summary.toolBreakdown.applitools = { passed: 0, failed: 0, new: 0, unresolved: 0 };
        }

        const toolResults = result.tools.applitools;

        if (toolResults.status === 'Passed') {
          report.summary.passed++;
          report.summary.toolBreakdown.applitools.passed++;
        } else if (toolResults.status === 'Failed') {
          report.summary.failed++;
          report.summary.toolBreakdown.applitools.failed++;
        } else if (toolResults.status === 'New') {
          report.summary.newBaselines++;
          report.summary.toolBreakdown.applitools.new++;
        } else if (toolResults.status === 'Unresolved') {
          report.summary.unresolved++;
          report.summary.toolBreakdown.applitools.unresolved++;
        }
      }
    }

    return report;
  }
}

