module.exports = VisualTestingFramework;

// types/visual-testing.ts - Type definitions for visual testing

type MatchLevel = 'Strict' | 'Content' | 'Layout' | 'Exact';
type BrowserName = 'chrome' | 'firefox' | 'safari' | 'edge';

interface ViewportConfig {
  width: number;
  height: number;
  name: string;
  deviceScaleFactor?: number;
  isMobile?: boolean;
  hasTouch?: boolean;
}

interface VisualTestConfig {
  name: string;
  url: string;
  viewports: ViewportConfig[];
  ignoreSelectors: string[];
  floatingRegions: Array<{
    selector: string;
    maxUpOffset: number;
    maxDownOffset: number;
    maxLeftOffset: number;
    maxRightOffset: number;
  }>;
  accessibilityRegions: Array<{
    selector: string;
    type: 'RegularText' | 'LargeText' | 'BoldText' | 'GraphicalObject' | 'IgnoreContrast';
  }>;
  waitForSelectors: string[];
  matchLevel: MatchLevel;
  fullPage: boolean;
  enableDomCapture: boolean;
  enablePatterns: boolean;
}

interface VisualTestResult {
  testName: string;
  status: 'passed' | 'failed' | 'new' | 'unresolved' | 'aborted';
  differences?: Array<{
    region: string;
    diffPercentage: number;
    diffImageUrl: string;
    baselineUrl: string;
    checkpointUrl: string;
  }>;
  metadata: {
    viewport: ViewportConfig;
    browser: BrowserName;
    timestamp: string;
    executionTime: number;
  };
  accessibilityIssues?: Array<{
    type: string;
    description: string;
    selector: string;
    contrastRatio?: number;
  }>;
}

// BaseVisualPage.ts - Abstract base class for visual page objects
export abstract class BaseVisualPage {
  protected page: any; // WebDriverIO/Playwright page object
  protected eyes: any; // Applitools Eyes instance
  protected config: VisualTestConfig;

  constructor(page: any, eyes: any, config: Partial<VisualTestConfig> = {}) {
    this.page = page;
    this.eyes = eyes;
    this.config = this.getDefaultConfig();
    Object.assign(this.config, config);
  }

  abstract getPageConfig(): VisualTestConfig;

  protected getDefaultConfig(): VisualTestConfig {
    return {
      name: this.constructor.name,
      url: '',
      viewports: [
        { width: 1920, height: 1080, name: 'Desktop Large' },
        { width: 1366, height: 768, name: 'Desktop Medium' },
        { width: 768, height: 1024, name: 'Tablet Portrait', isMobile: true, hasTouch: true },
        { width: 375, height: 667, name: 'Mobile', isMobile: true, hasTouch: true, deviceScaleFactor: 2 }
      ],
      ignoreSelectors: [],
      floatingRegions: [],
      accessibilityRegions: [],
      waitForSelectors: [],
      matchLevel: 'Layout',
      fullPage: true,
      enableDomCapture: true,
      enablePatterns: true
    };
  }

  async navigate(): Promise<void> {
    if (!this.config.url) {
      throw new Error('URL not configured for this page');
    }

    await this.page.goto(this.config.url);
    await this.waitForStability();
  }

  async waitForStability(): Promise<void> {
    // Wait for network idle
    await this.page.waitForLoadState('networkidle');

    // Wait for specific selectors
    for (const selector of this.config.waitForSelectors) {
      try {
        await this.page.waitForSelector(selector, { state: 'visible', timeout: 10000 });
      } catch (error) {
        console.warn(`Selector ${selector} not found or not visible`);
      }
    }

    // Wait for animations to complete
    await this.page.waitForTimeout(1000);
  }

  async takeVisualSnapshot(snapshotName: string): Promise<VisualTestResult> {
    if (!this.eyes) {
      throw new Error('Visual testing tool not initialized');
    }

    const startTime = Date.now();

    try {
      // Configure target with all settings
      let target = this.eyes.Target.window()
        .fully(this.config.fullPage)
        .layout() // Default match level, will be overridden
        .ignoreCaret(true)
        .sendDom(this.config.enableDomCapture)
        .enablePatterns(this.config.enablePatterns);

      // Set match level
      switch (this.config.matchLevel) {
        case 'Strict':
          target = target.strict();
          break;
        case 'Content':
          target = target.content();
          break;
        case 'Exact':
          target = target.exact();
          break;
        default:
          target = target.layout();
      }

      // Add ignore regions
      if (this.config.ignoreSelectors.length > 0) {
        target = target.ignoreRegions(...this.config.ignoreSelectors.map(selector => 
          this.eyes.Target.regionBySelector(selector)
        ));
      }

      // Add floating regions
      this.config.floatingRegions.forEach(region => {
        target = target.floatingRegion(
          this.eyes.Target.regionBySelector(region.selector),
          region.maxUpOffset,
          region.maxDownOffset,
          region.maxLeftOffset,
          region.maxRightOffset
        );
      });

      // Add accessibility regions
      this.config.accessibilityRegions.forEach(region => {
        target = target.accessibilityRegion(
          this.eyes.Target.regionBySelector(region.selector),
          region.type
        );
      });

      // Take screenshot
      await this.eyes.check(snapshotName, target);

      const executionTime = Date.now() - startTime;

      return {
        testName: snapshotName,
        status: 'passed', // Simplified - actual status comes from eyes.close()
        metadata: {
          viewport: this.config.viewports[0],
          browser: 'chrome', // Should be dynamic
          timestamp: new Date().toISOString(),
          executionTime
        }
      };

    } catch (error) {
      return {
        testName: snapshotName,
        status: 'failed',
        metadata: {
          viewport: this.config.viewports[0],
          browser: 'chrome',
          timestamp: new Date().toISOString(),
          executionTime: Date.now() - startTime
        }
      };
    }
  }

  async testResponsive(): Promise<VisualTestResult[]> {
    const results: VisualTestResult[] = [];
    const originalViewport = this.config.viewports[0];

    for (const viewport of this.config.viewports) {
      // Update page viewport
      await this.page.setViewportSize({ width: viewport.width, height: viewport.height });
      await this.page.waitForTimeout(500); // Allow for resize

      // Update config for this viewport
      this.config.viewports = [viewport];

      const testName = `${this.constructor.name} - ${viewport.name}`;
      const result = await this.takeVisualSnapshot(testName);
      results.push(result);
    }

    // Restore original viewport
    this.config.viewports = [originalViewport];
    await this.page.setViewportSize({ width: originalViewport.width, height: originalViewport.height });

    return results;
  }

  async testComponent(selector: string, componentName: string): Promise<VisualTestResult> {
    const target = this.eyes.Target.regionBySelector(selector).layout();

    try {
      await this.eyes.check(`${componentName} Component`, target);

      return {
        testName: `${componentName} Component`,
        status: 'passed',
        metadata: {
          viewport: this.config.viewports[0],
          browser: 'chrome',
          timestamp: new Date().toISOString(),
          executionTime: 0
        }
      };
    } catch (error) {
      return {
        testName: `${componentName} Component`,
        status: 'failed',
        metadata: {
          viewport: this.config.viewports[0],
          browser: 'chrome',
          timestamp: new Date().toISOString(),
          executionTime: 0
        }
      };
    }
  }
}

