import { BaseVisualPage } from './BaseVisualPage';

export class HomePage extends BaseVisualPage {
  getPageConfig(): VisualTestConfig {
    return {
      name: 'Homepage',
      url: 'https://example.com',
      viewports: this.getDefaultConfig().viewports,
      ignoreSelectors: [
        '.live-news-ticker',
