// VisualTestRunner.ts - Test runner orchestration
export class VisualTestRunner {
  private eyes: any;
  private page: any;
  private results: VisualTestResult[] = [];

  constructor(private browserType: 'chromium' | 'firefox' | 'webkit' = 'chromium') {}

  async setup() {
    const { chromium } = require('playwright');
    const { Eyes, ClassicRunner } = require('@applitools/eyes-playwright');

    // Launch browser
    const browser = await chromium.launch({
      headless: process.env.CI === 'true',
      args: ['--no-sandbox', '--disable-dev-shm-usage']
    });

    this.page = await browser.newPage({
      viewport: { width: 1920, height: 1080 },
      locale: 'en-US'
    });

    // Initialize Applitools
    const runner = new ClassicRunner();
    this.eyes = new Eyes(runner);

    if (process.env.APPLITOOLS_API_KEY) {
      this.eyes.setApiKey(process.env.APPLITOOLS_API_KEY);
    }

    const configuration = this.eyes.getConfiguration();
    configuration.setAppName('E-commerce Visual Tests');
    configuration.setTestName('Comprehensive Visual Regression');
    configuration.setBatch({
      name: 'Automated Test Run',
      id: process.env.CI_COMMIT_SHA || `local-${Date.now()}`
    });
    configuration.setMatchLevel('Layout');
    configuration.setIgnoreDisplacements(true);
    configuration.setSendDom(true);
    configuration.setEnablePatterns(true);

    // Configure accessibility validation
    configuration.setAccessibilityValidation({
      level: 'AA',
      guidelinesVersion: 'WCAG_2_1'
    });

    this.eyes.setConfiguration(configuration);
  }

  async runHomepageTests() {
    await this.eyes.open(this.page);

    const homePage = new HomePage(this.page, this.eyes);
    await homePage.navigate();

    // Full page test
    this.results.push(await homePage.takeVisualSnapshot('Homepage Full'));

    // Component tests
    this.results.push(await homePage.testHeroBanner());
    this.results.push(await homePage.testProductGrid());
    this.results.push(await homePage.testNavigation());

    // Responsive tests
    const responsiveResults = await homePage.testResponsive();
    this.results.push(...responsiveResults);

    // Interactive test
    const searchResults = await homePage.testSearchInteraction('laptop');
    this.results.push(...searchResults);
  }

  async runCheckoutTests(testData: any) {
    await this.eyes.open(this.page);

    const checkoutPage = new CheckoutPage(this.page, this.eyes, testData);
    await checkoutPage.navigate();

    // Form filling visual tests
    const shippingResults = await checkoutPage.fillShippingAddress(testData.shippingAddress);
    this.results.push(...shippingResults);

    // Payment method selection
    this.results.push(await checkoutPage.selectPaymentMethod('credit-card'));

    // Form validation tests
    const validationResults = await checkoutPage.testFormValidation();
    this.results.push(...validationResults);
  }

  async teardown() {
    if (this.eyes) {
      const testResults = await this.eyes.close(false);
      console.log('Applitools results:', testResults);
    }

    if (this.page) {
      await this.page.close();
    }
  }

  generateReport() {
    const summary = {
      totalTests: this.results.length,
      passed: this.results.filter(r => r.status === 'passed').length,
      failed: this.results.filter(r => r.status === 'failed').length,
      new: this.results.filter(r => r.status === 'new').length,
      unresolved: this.results.filter(r => r.status === 'unresolved').length,
      executionTime: this.results.reduce((sum, r) => sum + (r.metadata?.executionTime || 0), 0)
    };

    return {
      summary,
      details: this.results,
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development'
    };
  }
}

// Main execution
async function main() {
  const runner = new VisualTestRunner();

  try {
    await runner.setup();

    // Run homepage tests
    await runner.runHomepageTests();

    // Run checkout tests with sample data
    await runner.runCheckoutTests({
      orderId: 'TEST-123',
      shippingAddress: {
        name: 'John Doe',
        street: '123 Main St',
        city: 'Anytown',
        country: 'US',
        zipCode: '12345'
      }
    });

    // Generate report
    const report = runner.generateReport();
    console.log(JSON.stringify(report, null, 2));

    // Save report to file
    const fs = require('fs').promises;
    await fs.writeFile('visual-test-report.json', JSON.stringify(report, null, 2));

    // Exit with appropriate code
    if (report.summary.failed > 0) {
      process.exit(1);
    }

  } catch (error) {
    console.error('Visual testing failed:', error);
    process.exit(1);
  } finally {
    await runner.teardown();
  }
}

