// advanced-baseline-manager.js
// Comprehensive baseline management with intelligent comparison and self-healing

const fs = require('fs-extra');
const path = require('path');
const crypto = require('crypto');
const { PNG } = require('pngjs');
const pixelmatch = require('pixelmatch');

class SmartBaselineManager {
  constructor(config = {}) {
    this.config = {
      baselineDir: './visual-baselines',
      historyDir: './visual-history',
      diffDir: './visual-diffs',
      maxHistory: 100,
      autoApproveThreshold: 0.01, // 1% difference auto-approved
      criticalThreshold: 0.05, // 5% difference requires review
      warningThreshold: 0.02, // 2% difference warning
      ignorePatterns: [
        'timestamp',
        'session-id',
        'user-id',
        'cache-buster',
        'current-time',
        'live-data'
      ],
      floatingTolerance: 5, // pixels
      colorTolerance: 0.1, // 10% color difference tolerance
      enableSelfHealing: true,
      selfHealingPatterns: [
        'timestamp',
        'date',
        'nonce',
        'cache-key'
      ],
      requireApprovalFor: [
        'layout-changes',
        'color-changes',
        'font-changes',
        'branding'
      ],
      ...config
    };

    this.ensureDirectories();
    this.loadBaselineMetadata();
  }

  ensureDirectories() {
    fs.ensureDirSync(this.config.baselineDir);
    fs.ensureDirSync(this.config.historyDir);
    fs.ensureDirSync(this.config.diffDir);
  }

  loadBaselineMetadata() {
    const metadataPath = path.join(this.config.baselineDir, 'metadata.json');

    try {
      if (fs.existsSync(metadataPath)) {
        this.metadata = JSON.parse(fs.readFileSync(metadataPath, 'utf8'));
      } else {
        this.metadata = {
          baselines: {},
          history: [],
          statistics: {
            totalComparisons: 0,
            passed: 0,
            failed: 0,
            autoApproved: 0,
            manualApprovals: 0
          }
        };
      }
    } catch (error) {
      console.warn('Failed to load baseline metadata:', error.message);
      this.metadata = {
        baselines: {},
        history: [],
        statistics: { totalComparisons: 0, passed: 0, failed: 0, autoApproved: 0, manualApprovals: 0 }
      };
    }
  }

  saveBaselineMetadata() {
    const metadataPath = path.join(this.config.baselineDir, 'metadata.json');
    fs.writeFileSync(metadataPath, JSON.stringify(this.metadata, null, 2));
  }

  async compareWithBaseline(testName, currentImage, metadata = {}) {
    const baselinePath = this.getBaselinePath(testName);

    // Update statistics
    this.metadata.statistics.totalComparisons++;

    // Check if baseline exists
    if (!fs.existsSync(baselinePath)) {
      return this.handleNewBaseline(testName, currentImage, metadata);
    }

    const baselineImage = fs.readFileSync(baselinePath);
    const baselineHash = this.calculateHash(baselineImage);
    const currentHash = this.calculateHash(currentImage);

    // Quick hash comparison (exact match)
    if (baselineHash === currentHash) {
      this.metadata.statistics.passed++;
      this.saveBaselineMetadata();

      return {
        status: 'identical',
        difference: 0,
        action: 'none',
        message: 'Images are identical',
        comparisonMethod: 'hash_comparison'
      };
    }

    // Perform pixel-by-pixel comparison with intelligence
    const comparison = await this.intelligentPixelComparison(
      baselinePath,
      currentImage,
      testName,
      metadata
    );

    // Archive old baseline before potentially updating
    await this.archiveBaseline(testName, baselineImage, {
      reason: 'comparison_triggered',
      comparisonResult: comparison,
      metadata
    });

    // Determine action based on comparison results
    const action = this.determineAction(comparison, testName);

    // Update statistics based on action
    switch (action) {
      case 'auto_approve':
        this.metadata.statistics.autoApproved++;
        break;
      case 'require_approval':
        this.metadata.statistics.failed++;
        break;
      case 'self_heal':
        this.metadata.statistics.passed++;
        break;
    }

    this.saveBaselineMetadata();

    return {
      status: comparison.status,
      difference: comparison.difference,
      action,
      details: comparison.details,
      diffImage: comparison.diffImage,
      baseline: baselinePath,
      current: currentImage,
      metadata: {
        testName,
        timestamp: new Date().toISOString(),
        ...metadata
      }
    };
  }

  async intelligentPixelComparison(baselinePath, currentImage, testName, metadata) {
    const startTime = Date.now();

    // Read images
    const baselinePNG = PNG.sync.read(fs.readFileSync(baselinePath));
    const currentPNG = PNG.sync.read(currentImage);

    // Create diff image
    const { width, height } = baselinePNG;
    const diff = new PNG({ width, height });

    // Perform pixel comparison with custom options
    const mismatchedPixels = pixelmatch(
      baselinePNG.data,
      currentPNG.data,
      diff.data,
      width,
      height,
      {
        threshold: 0.1,
        includeAA: false,
        alpha: 0.1,
        diffColor: [255, 0, 0], // Red for differences
        diffColorAlt: [0, 0, 255] // Blue for alternative differences
      }
    );

    const totalPixels = width * height;
    const differencePercentage = (mismatchedPixels / totalPixels) * 100;

    // Analyze difference pattern
    const patternAnalysis = await this.analyzeDifferencePattern(
      baselinePNG,
      currentPNG,
      diff,
      mismatchedPixels
    );

    // Check for self-healing patterns
    const selfHealingResult = await this.checkSelfHealingPatterns(
      patternAnalysis,
      testName,
      metadata
    );

    // Generate diff image
    const diffImagePath = path.join(
      this.config.diffDir,
      `${testName.replace(/[^a-z0-9]/gi, '_')}_${Date.now()}.png`
    );
    fs.writeFileSync(diffImagePath, PNG.sync.write(diff));

    const executionTime = Date.now() - startTime;

    return {
      difference: differencePercentage,
      mismatchedPixels,
      totalPixels,
      width,
      height,
      status: this.getStatusFromDifference(differencePercentage),
      details: {
        patternAnalysis,
        selfHealingResult,
        executionTime,
        comparisonMethod: 'intelligent_pixel_comparison',
        imageDimensions: { width, height }
      },
      diffImage: diffImagePath,
      patternAnalysis
    };
  }

  async analyzeDifferencePattern(baselinePNG, currentPNG, diffPNG, mismatchedPixels) {
    const analysis = {
      regions: [],
      patternType: 'unknown',
      isSystematic: false,
      isLocalized: false,
      affectedAreas: []
    };

    const { width, height } = baselinePNG;

    // Analyze diff image to find connected regions
    const visited = new Array(width * height).fill(false);
    const diffData = diffPNG.data;

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const idx = (width * y + x) * 4;

        // Check if this pixel is different (red or blue in diff)
        if ((diffData[idx] === 255 && diffData[idx + 1] === 0 && diffData[idx + 2] === 0) || // Red
            (diffData[idx] === 0 && diffData[idx + 1] === 0 && diffData[idx + 2] === 255)) { // Blue

          if (!visited[width * y + x]) {
            const region = this.floodFill(x, y, diffData, visited, width, height);
            if (region.pixels > 10) { // Ignore tiny regions
              analysis.regions.push(region);
            }
          }
        }
      }
    }

    // Analyze region patterns
    if (analysis.regions.length > 0) {
      const totalRegionPixels = analysis.regions.reduce((sum, r) => sum + r.pixels, 0);

      // Check if differences are localized or spread out
      analysis.isLocalized = analysis.regions.length <= 3 && 
                            totalRegionPixels < mismatchedPixels * 0.5;

      // Check for systematic patterns (grid, repeated patterns)
      analysis.isSystematic = this.checkForSystematicPattern(analysis.regions);

      // Determine pattern type
      analysis.patternType = this.determinePatternType(analysis.regions, baselinePNG, currentPNG);
    }

    return analysis;
  }

  floodFill(startX, startY, diffData, visited, width, height) {
    const region = {
      minX: startX,
      maxX: startX,
      minY: startY,
      maxY: startY,
      pixels: 0,
      centroid: { x: 0, y: 0 }
    };

    const stack = [[startX, startY]];

    while (stack.length > 0) {
      const [x, y] = stack.pop();
      const idx = width * y + x;

      if (visited[idx]) continue;
      if (x < 0 || x >= width || y < 0 || y >= height) continue;

      const pixelIdx = (width * y + x) * 4;
      const isDiff = (diffData[pixelIdx] === 255 && diffData[pixelIdx + 1] === 0 && diffData[pixelIdx + 2] === 0) ||
                     (diffData[pixelIdx] === 0 && diffData[pixelIdx + 1] === 0 && diffData[pixelIdx + 2] === 255);

      if (!isDiff) continue;

      visited[idx] = true;
      region.pixels++;
      region.minX = Math.min(region.minX, x);
      region.maxX = Math.max(region.maxX, x);
      region.minY = Math.min(region.minY, y);
      region.maxY = Math.max(region.maxY, y);
      region.centroid.x += x;
      region.centroid.y += y;

      // Check neighbors
      stack.push([x + 1, y]);
      stack.push([x - 1, y]);
      stack.push([x, y + 1]);
      stack.push([x, y - 1]);
    }

    if (region.pixels > 0) {
      region.centroid.x /= region.pixels;
      region.centroid.y /= region.pixels;
      region.width = region.maxX - region.minX + 1;
      region.height = region.maxY - region.minY + 1;
    }

    return region;
  }

  checkForSystematicPattern(regions) {
    if (regions.length < 3) return false;

    // Check for grid pattern
    const xs = regions.map(r => r.centroid.x).sort((a, b) => a - b);
    const ys = regions.map(r => r.centroid.y).sort((a, b) => a - b);

    const xSpacing = this.calculateRegularSpacing(xs);
    const ySpacing = this.calculateRegularSpacing(ys);

    return xSpacing.regular && ySpacing.regular;
  }

  calculateRegularSpacing(values) {
    if (values.length < 3) return { regular: false, spacing: 0 };

    const spacings = [];
    for (let i = 1; i < values.length; i++) {
      spacings.push(values[i] - values[i - 1]);
    }

    const avgSpacing = spacings.reduce((sum, s) => sum + s, 0) / spacings.length;
    const variance = spacings.reduce((sum, s) => sum + Math.pow(s - avgSpacing, 2), 0) / spacings.length;

    return {
      regular: variance < avgSpacing * 0.1, // Less than 10% variance
      spacing: avgSpacing
    };
  }

  determinePatternType(regions, baselinePNG, currentPNG) {
    if (regions.length === 0) return 'none';

    // Analyze region characteristics
    const largeRegions = regions.filter(r => r.pixels > 100);
    const smallRegions = regions.filter(r => r.pixels <= 100);

    if (largeRegions.length > 0) {
      // Check if large regions are text-like (tall and narrow)
      const textLike = largeRegions.filter(r => r.height > r.width * 2).length > 0;

      if (textLike) return 'text_changes';

      // Check for color changes
      const firstRegion = largeRegions[0];
      const baselineColor = this.getRegionColor(baselinePNG, firstRegion);
      const currentColor = this.getRegionColor(currentPNG, firstRegion);

      if (this.isColorChange(baselineColor, currentColor)) {
        return 'color_changes';
      }

      return 'layout_changes';
    }

    if (smallRegions.length > 10) {
      return 'noise_or_antialiasing';
    }

    return 'minor_changes';
  }

  async checkSelfHealingPatterns(patternAnalysis, testName, metadata) {
    if (!this.config.enableSelfHealing) {
      return { canSelfHeal: false, reason: 'self_healing_disabled' };
    }

    // Check test metadata for known self-healing patterns
    const testMetadata = this.metadata.baselines[testName];
    if (testMetadata && testMetadata.selfHealingPatterns) {
      for (const pattern of testMetadata.selfHealingPatterns) {
        if (patternAnalysis.patternType === pattern.type) {
          return { 
            canSelfHeal: true, 
            pattern,
            confidence: pattern.confidence || 0.8 
          };
        }
      }
    }

    // Check for timestamp patterns
    if (this.isTimestampPattern(patternAnalysis)) {
      return {
        canSelfHeal: true,
        pattern: { type: 'timestamp', confidence: 0.95 },
        reason: 'Detected timestamp pattern'
      };
    }

    // Check for dynamic content patterns from metadata
    if (metadata.url && this.config.ignorePatterns.some(pattern => 
      metadata.url.includes(pattern) || metadata.url.includes(pattern.replace('-', '_'))
    )) {
      return {
        canSelfHeal: true,
        pattern: { type: 'dynamic_content', confidence: 0.9 },
        reason: 'Dynamic content detected in URL'
      };
    }

    return { canSelfHeal: false, reason: 'no_matching_patterns' };
  }

  determineAction(comparison, testName) {
    // Self-healing takes priority
    if (comparison.details.selfHealingResult.canSelfHeal) {
      return 'self_heal';
    }

    // Check thresholds
    if (comparison.difference <= this.config.autoApproveThreshold) {
      return 'auto_approve';
    }

    if (comparison.difference >= this.config.criticalThreshold) {
      return 'require_approval_critical';
    }

    if (comparison.difference >= this.config.warningThreshold) {
      return 'require_approval_warning';
    }

    // Check pattern type
    if (this.config.requireApprovalFor.includes(comparison.details.patternAnalysis.patternType)) {
      return 'require_approval_pattern';
    }

    return 'require_review';
  }

  async handleNewBaseline(testName, image, metadata) {
    const baselinePath = this.getBaselinePath(testName);

    // Save new baseline
    fs.writeFileSync(baselinePath, image);

    // Update metadata
    this.metadata.baselines[testName] = {
      created: new Date().toISOString(),
      createdBy: metadata.user || 'system',
      hash: this.calculateHash(image),
      size: image.length,
      dimensions: await this.getImageDimensions(image),
      metadata
    };

    this.saveBaselineMetadata();

    return {
      status: 'new',
      difference: 1.0,
      action: 'require_approval',
      message: 'New baseline created, requires approval',
      baseline: baselinePath
    };
  }

  async updateBaseline(testName, image, reason = 'manual_approval', approvedBy = 'system') {
    const baselinePath = this.getBaselinePath(testName);

    // Archive current baseline if it exists
    if (fs.existsSync(baselinePath)) {
      const currentBaseline = fs.readFileSync(baselinePath);
      await this.archiveBaseline(testName, currentBaseline, {
        reason: 'updated',
        newReason: reason,
        approvedBy
      });
    }

    // Write new baseline
    fs.writeFileSync(baselinePath, image);

    // Update metadata
    this.metadata.baselines[testName] = {
      ...(this.metadata.baselines[testName] || {}),
      updated: new Date().toISOString(),
      updatedBy: approvedBy,
      updateReason: reason,
      hash: this.calculateHash(image),
      size: image.length,
      dimensions: await this.getImageDimensions(image),
      lastComparison: new Date().toISOString()
    };

    // Record in history
    this.metadata.history.push({
      testName,
      action: 'baseline_update',
      timestamp: new Date().toISOString(),
      reason,
      approvedBy,
      hash: this.calculateHash(image)
    });

    // Trim history if too long
    if (this.metadata.history.length > this.config.maxHistory) {
      this.metadata.history = this.metadata.history.slice(-this.config.maxHistory);
    }

    this.saveBaselineMetadata();

    return baselinePath;
  }

  async archiveBaseline(testName, image, metadata) {
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const archiveDir = path.join(this.config.historyDir, testName);
    const archivePath = path.join(archiveDir, `${timestamp}.png`);

    fs.ensureDirSync(archiveDir);

    // Write archived image
    fs.writeFileSync(archivePath, image);

    // Write metadata
    const metaPath = archivePath.replace('.png', '.json');
    fs.writeFileSync(metaPath, JSON.stringify({
      testName,
      archivedAt: timestamp,
      hash: this.calculateHash(image),
      size: image.length,
      ...metadata
    }, null, 2));

    // Clean up old archives
    await this.cleanupOldArchives(testName);

    return archivePath;
  }

  // Helper methods
  calculateHash(data) {
    return crypto.createHash('sha256').update(data).digest('hex');
  }

  getBaselinePath(testName) {
    const safeName = testName.replace(/[^a-z0-9]/gi, '_').toLowerCase();
    return path.join(this.config.baselineDir, `${safeName}.png`);
  }

  getStatusFromDifference(difference) {
    if (difference === 0) return 'identical';
    if (difference <= this.config.autoApproveThreshold) return 'minor_difference';
    if (difference <= this.config.warningThreshold) return 'warning';
    if (difference <= this.config.criticalThreshold) return 'significant_difference';
    return 'major_difference';
  }

  async getImageDimensions(imageBuffer) {
    return new Promise((resolve, reject) => {
      try {
        const png = PNG.sync.read(imageBuffer);
        resolve({ width: png.width, height: png.height });
      } catch (error) {
        reject(new Error(`Failed to read image dimensions: ${error.message}`));
      }
    });
  }

  getRegionColor(png, region) {
    // Get average color in region
    let r = 0, g = 0, b = 0, a = 0;
    let count = 0;

    for (let y = region.minY; y <= region.maxY; y++) {
      for (let x = region.minX; x <= region.maxX; x++) {
        const idx = (png.width * y + x) * 4;
        r += png.data[idx];
        g += png.data[idx + 1];
        b += png.data[idx + 2];
        a += png.data[idx + 3];
        count++;
      }
    }

    if (count === 0) return { r: 0, g: 0, b: 0, a: 0 };

    return {
      r: Math.round(r / count),
      g: Math.round(g / count),
      b: Math.round(b / count),
      a: Math.round(a / count)
    };
  }

  isColorChange(color1, color2) {
    // Calculate color difference using Euclidean distance in RGB space
    const dr = color1.r - color2.r;
    const dg = color1.g - color2.g;
    const db = color1.b - color2.b;
    const distance = Math.sqrt(dr * dr + dg * dg + db * db);

    // Consider it a color change if distance > 30 (out of 255)
    return distance > 30;
  }

  isTimestampPattern(patternAnalysis) {
    // Simple check for timestamp-like patterns
    // Timestamps often appear as small, rectangular regions with numbers
    if (patternAnalysis.regions.length < 4) return false;

    // Check if regions are horizontally aligned and similar size
    const firstRegion = patternAnalysis.regions[0];
    const similarRegions = patternAnalysis.regions.filter(r => 
      Math.abs(r.height - firstRegion.height) < 5 &&
      Math.abs(r.width - firstRegion.width) < 10
    );

    return similarRegions.length >= 4;
  }

  async cleanupOldArchives(testName) {
    const archiveDir = path.join(this.config.historyDir, testName);

    if (!fs.existsSync(archiveDir)) {
      return;
    }

    const files = fs.readdirSync(archiveDir)
      .filter(f => f.endsWith('.png'))
      .map(f => ({
        name: f,
        path: path.join(archiveDir, f),
        time: fs.statSync(path.join(archiveDir, f)).mtime.getTime()
      }))
      .sort((a, b) => b.time - a.time);

    // Remove files beyond maxHistory
    if (files.length > this.config.maxHistory) {
      const toRemove = files.slice(this.config.maxHistory);
      toRemove.forEach(file => {
        fs.unlinkSync(file.path);
        // Also remove metadata file
        const metaPath = file.path.replace('.png', '.json');
        if (fs.existsSync(metaPath)) {
          fs.unlinkSync(metaPath);
        }
      });
    }
  }

  // Batch operations
  async batchCompare(testResults) {
    const comparisons = [];
    const summary = {
      total: testResults.length,
      identical: 0,
      minorDifferences: 0,
      significantDifferences: 0,
      majorDifferences: 0,
      newTests: 0,
      autoApproved: 0,
      selfHealed: 0,
      requiresApproval: 0,
      requiresReview: 0
    };

    for (const result of testResults) {
      const comparison = await this.compareWithBaseline(
        result.testName,
        result.screenshot,
        result.metadata
      );

      comparisons.push({
        testName: result.testName,
        ...comparison
      });

      // Update summary
      switch (comparison.status) {
        case 'identical':
          summary.identical++;
          break;
        case 'minor_difference':
          summary.minorDifferences++;
          if (comparison.action === 'auto_approve') summary.autoApproved++;
          break;
        case 'significant_difference':
          summary.significantDifferences++;
          summary.requiresApproval++;
          break;
        case 'major_difference':
          summary.majorDifferences++;
          summary.requiresApproval++;
          break;
        case 'new':
          summary.newTests++;
          summary.requiresApproval++;
          break;
      }

      if (comparison.action === 'self_heal') {
        summary.selfHealed++;
      }
    }

    return {
      summary,
      comparisons,
      metadata: {
        generatedAt: new Date().toISOString(),
        baselineManagerVersion: '1.0.0',
        config: {
          autoApproveThreshold: this.config.autoApproveThreshold,
          criticalThreshold: this.config.criticalThreshold
        }
      }
    };
  }

  // Generate comprehensive report
  async generateComparisonReport(batchResults, outputPath) {
    const report = {
      title: 'Visual Regression Test Report',
      batchId: `batch_${Date.now()}`,
      timestamp: new Date().toISOString(),
