// test-optimization-engine.js
// Advanced performance optimization for visual testing

class VisualTestOptimizer {
  constructor(config = {}) {
    this.config = {
      maxParallelBrowsers: 4,
      testTimeout: 300000,
      resourceThreshold: 0.8,
      cacheEnabled: true,
      selectiveTesting: true,
      ...config
    };

    this.testRegistry = new Map();
    this.resourceMonitor = new ResourceMonitor();
    this.cacheManager = new TestCacheManager();
    this.dependencyGraph = new DependencyGraph();
  }

  async optimizeTestSuite(testSuite, changeSet = null) {
    const optimizationStart = Date.now();

    // 1. Analyze dependencies and build graph
    this.buildDependencyGraph(testSuite);

    // 2. Apply selective testing based on changes
    let testsToRun = this.applySelectiveTesting(testSuite, changeSet);

    // 3. Optimize test order for maximum parallelization
    testsToRun = this.optimizeExecutionOrder(testsToRun);

    // 4. Batch tests for efficient resource utilization
    const batches = this.createOptimizedBatches(testsToRun);

    // 5. Allocate resources based on test requirements
    const resourceAllocation = this.allocateResources(batches);

    const optimizationTime = Date.now() - optimizationStart;

    return {
      originalCount: testSuite.length,
      optimizedCount: testsToRun.length,
      reduction: ((testSuite.length - testsToRun.length) / testSuite.length * 100).toFixed(1),
      batches,
      resourceAllocation,
      estimatedTimeReduction: this.estimateTimeReduction(testsToRun, batches),
      optimizationTime,
      metadata: {
        changeSetSize: changeSet ? changeSet.length : 0,
        dependencyGraphSize: this.dependencyGraph.size,
        cacheHitRate: this.cacheManager.getHitRate()
      }
    };
  }

  buildDependencyGraph(testSuite) {
    // Build dependency graph for intelligent test ordering
    testSuite.forEach(test => {
      this.dependencyGraph.addNode(test.id, {
        resources: test.resources || {},
        dependencies: test.dependencies || [],
        priority: test.priority || 'medium',
        executionTime: test.avgExecutionTime || 30000
      });
    });

    // Calculate critical paths
    this.dependencyGraph.calculateCriticalPaths();
  }

  applySelectiveTesting(testSuite, changeSet) {
    if (!this.config.selectiveTesting || !changeSet) {
      return testSuite;
    }

    // Map changes to affected tests
    const affectedTests = new Set();

    changeSet.forEach(change => {
      // Analyze change type and affected components
      const changeAnalysis = this.analyzeChange(change);

      // Find tests that cover affected components
      const relatedTests = this.findRelatedTests(changeAnalysis);

      relatedTests.forEach(testId => {
        affectedTests.add(testId);

        // Also include dependent tests
        const dependents = this.dependencyGraph.getDependents(testId);
        dependents.forEach(dependent => affectedTests.add(dependent));
      });
    });

    // Include all high-priority tests regardless of changes
    testSuite.forEach(test => {
      if (test.priority === 'critical') {
        affectedTests.add(test.id);
      }
    });

    // Check cache for unaffected tests
    testSuite.forEach(test => {
      if (!affectedTests.has(test.id) && this.cacheManager.isValid(test.id)) {
        // Test result is cached and still valid
        console.log(`Skipping ${test.id} - result cached`);
      } else if (!affectedTests.has(test.id) && test.priority === 'low') {
        // Skip low priority tests not affected by changes
        console.log(`Skipping ${test.id} - low priority and unaffected`);
      } else if (!affectedTests.has(test.id)) {
        // Medium priority tests not affected - run a subset
        if (Math.random() < 0.3) { // Run 30% of unaffected medium priority tests
          affectedTests.add(test.id);
        }
      }
    });

    return testSuite.filter(test => affectedTests.has(test.id));
  }

  optimizeExecutionOrder(tests) {
    // Reorder tests for optimal parallel execution
    return tests.sort((a, b) => {
      // Critical tests first
      if (a.priority === 'critical' && b.priority !== 'critical') return -1;
      if (b.priority === 'critical' && a.priority !== 'critical') return 1;

      // Group by resource requirements
      const aResources = this.calculateResourceScore(a);
      const bResources = this.calculateResourceScore(b);

      if (aResources !== bResources) {
        return aResources - bResources; // Lower resource requirements first
      }

      // Shorter tests before longer tests
      return (a.avgExecutionTime || 30000) - (b.avgExecutionTime || 30000);
    });
  }

  createOptimizedBatches(tests) {
    const batches = [];
    let currentBatch = [];
    let currentBatchResources = { browsers: 0, memory: 0, cpu: 0 };

    tests.forEach(test => {
      const testResources = this.estimateResourceRequirements(test);

      // Check if test fits in current batch
      if (this.canFitInBatch(currentBatchResources, testResources)) {
        currentBatch.push(test);
        currentBatchResources = this.addResources(currentBatchResources, testResources);
      } else {
        // Start new batch
        if (currentBatch.length > 0) {
          batches.push({
            tests: currentBatch,
            resources: currentBatchResources,
            estimatedTime: this.estimateBatchTime(currentBatch)
          });
        }

        currentBatch = [test];
        currentBatchResources = testResources;
      }
    });

    // Add last batch
    if (currentBatch.length > 0) {
      batches.push({
        tests: currentBatch,
        resources: currentBatchResources,
        estimatedTime: this.estimateBatchTime(currentBatch)
      });
    }

    return batches;
  }

  allocateResources(batches) {
    const allocation = [];
    let availableBrowsers = this.config.maxParallelBrowsers;

    // Allocate browsers to batches based on priority and resource needs
    batches.forEach((batch, index) => {
      const requiredBrowsers = Math.min(
        Math.ceil(batch.tests.length / 3), // Max 3 tests per browser
        availableBrowsers
      );

      allocation.push({
        batchIndex: index,
        browsers: requiredBrowsers,
        parallelTests: requiredBrowsers * 3,
        estimatedCompletion: this.calculateCompletionTime(batch, requiredBrowsers)
      });

      availableBrowsers -= requiredBrowsers;
    });

    return allocation;
  }

  // Helper methods
  analyzeChange(change) {
    // Analyze git change to determine affected components
    const { file, type, content } = change;

    return {
      fileType: this.getFileType(file),
      affectedComponents: this.extractComponentsFromFile(file, content),
      changeType: type,
      impactScore: this.calculateChangeImpact(change)
    };
  }

  findRelatedTests(changeAnalysis) {
    // Find tests that cover the affected components
    const relatedTests = [];

    this.testRegistry.forEach((test, testId) => {
      if (this.testCoversComponents(test, changeAnalysis.affectedComponents)) {
        relatedTests.push(testId);
      }
    });

    return relatedTests;
  }

  estimateTimeReduction(optimizedTests, batches) {
    // Simplified estimation
    const originalTime = optimizedTests.reduce((sum, test) => 
      sum + (test.avgExecutionTime || 30000), 0);

    const optimizedTime = batches.reduce((sum, batch) => {
      const batchTime = batch.estimatedTime;
      const parallelFactor = Math.min(batch.tests.length, 3);
      return sum + (batchTime / parallelFactor);
    }, 0);

    return {
      originalTime,
      optimizedTime,
      reduction: ((originalTime - optimizedTime) / originalTime * 100).toFixed(1)
    };
  }
}

// Resource monitoring class
class ResourceMonitor {
  constructor() {
    this.metrics = {
      cpu: [],
      memory: [],
      network: [],
      browserInstances: 0
    };
    this.thresholds = {
      cpu: 0.8, // 80%
      memory: 0.75, // 75%
      networkLatency: 100 // ms
    };
  }

  async monitor() {
    // Monitor system resources
    const metrics = await this.collectMetrics();
    this.metrics.cpu.push(metrics.cpu);
    this.metrics.memory.push(metrics.memory);
    this.metrics.network.push(metrics.network);

    // Keep only recent metrics
    this.trimMetrics();

    return this.getStatus();
  }

  getStatus() {
    const avgCpu = this.average(this.metrics.cpu);
    const avgMemory = this.average(this.metrics.memory);

    return {
      cpu: avgCpu,
      memory: avgMemory,
      network: this.metrics.network[this.metrics.network.length - 1],
      browserInstances: this.metrics.browserInstances,
      isOverloaded: avgCpu > this.thresholds.cpu || avgMemory > this.thresholds.memory
    };
  }

  canRunMoreTests() {
    const status = this.getStatus();
    return !status.isOverloaded && this.metrics.browserInstances < 10;
  }
}

// Test caching manager
class TestCacheManager {
  constructor() {
    this.cache = new Map();
    this.hits = 0;
    this.misses = 0;
  }

  async get(testId) {
    const entry = this.cache.get(testId);

    if (entry && this.isValid(entry)) {
      this.hits++;
      return entry.result;
    }

    this.misses++;
    return null;
  }

  async set(testId, result, dependencies = []) {
    this.cache.set(testId, {
      result,
      timestamp: Date.now(),
      dependencies,
      ttl: 3600000 // 1 hour
    });

    this.cleanup();
  }

  isValid(testIdOrEntry) {
    const entry = typeof testIdOrEntry === 'string' 
      ? this.cache.get(testIdOrEntry)
      : testIdOrEntry;

    if (!entry) return false;

    // Check TTL
    if (Date.now() - entry.timestamp > entry.ttl) {
      return false;
    }

    // Check if dependencies changed
    return this.checkDependencies(entry.dependencies);
  }

  getHitRate() {
    const total = this.hits + this.misses;
    return total > 0 ? (this.hits / total * 100).toFixed(1) : 0;
  }
}

// Dependency graph for test ordering
class DependencyGraph {
  constructor() {
    this.nodes = new Map();
    this.edges = new Map();
  }

  addNode(id, data) {
    this.nodes.set(id, { id, data });
    this.edges.set(id, new Set());
  }

  addDependency(from, to) {
    if (this.edges.has(from)) {
      this.edges.get(from).add(to);
    }
  }

  getDependents(nodeId) {
    const dependents = new Set();

    this.edges.forEach((dependencies, sourceId) => {
      if (dependencies.has(nodeId)) {
        dependents.add(sourceId);
      }
    });

    return Array.from(dependents);
  }

  calculateCriticalPaths() {
    // Calculate longest paths for scheduling
    this.criticalPaths = [];
