// dynamic-content-handler.js
// Advanced handling of dynamic content in visual tests

class DynamicContentHandler {
  constructor(config = {}) {
    this.config = {
      autoDetectDynamicContent: true,
      useAIForDetection: false,
      stabilizationTimeout: 5000,
      defaultIgnoreSelectors: [
        '[data-dynamic]',
        '[data-testid*="dynamic"]',
        '.timestamp',
        '.live-data',
        '[aria-live]'
      ],
      ...config
    };

    this.dynamicPatterns = this.initializePatterns();
    this.stabilizationStrategies = new Map();
    this.ignoreRegionsCache = new Map();
  }

  initializePatterns() {
    return [
      // Time patterns
      {
        type: 'timestamp',
        patterns: [
          /\d{1,2}:\d{2}(:\d{2})?\s*(AM|PM)?/i,
          /\d{4}-\d{2}-\d{2}/,
          /\d{1,2}\/\d{1,2}\/\d{4}/,
          /\d+\s+(seconds?|minutes?|hours?|days?|weeks?|months?|years?)\s+ago/i
        ],
        handling: 'mask'
      },

      // Number patterns
      {
        type: 'numeric_variable',
        patterns: [
          /\$?\d+(\.\d{1,2})?/,
          /\d+(\.\d+)?%/,
          /\d+\s*(k|K|m|M|b|B)?/,
          /#\d+/
        ],
        handling: 'normalize'
      },

      // User-specific patterns
      {
        type: 'user_data',
        patterns: [
          /user[-_]?id/i,
          /session[-_]?id/i,
          /[A-F0-9]{8}(?:-[A-F0-9]{4}){3}-[A-F0-9]{12}/i, // UUID
          /[a-z0-9]{32}/i // MD5 hash
        ],
        handling: 'stabilize'
      },

      // Live data patterns
      {
        type: 'live_data',
        patterns: [
          /stock[-_]?price/i,
          /exchange[-_]?rate/i,
          /weather[-_]?temp/i,
          /live[-_]?score/i
        ],
        handling: 'mock'
      }
    ];
  }

  async preparePageForVisualTest(page, url, options = {}) {
    const startTime = Date.now();
    const preparationSteps = [];

    // 1. Navigate to page
    await page.goto(url, { waitUntil: 'networkidle' });
    preparationSteps.push('page_navigated');

    // 2. Stabilize dynamic content
    await this.stabilizeDynamicContent(page, options.stabilizationSelectors);
    preparationSteps.push('content_stabilized');

    // 3. Detect and handle dynamic regions
    const dynamicRegions = await this.detectDynamicRegions(page);
    preparationSteps.push('dynamic_regions_detected');

    // 4. Apply ignore regions
    const ignoreRegions = await this.calculateIgnoreRegions(page, dynamicRegions);
    preparationSteps.push('ignore_regions_calculated');

    // 5. Wait for visual stability
    await this.waitForVisualStability(page);
    preparationSteps.push('visual_stability_achieved');

    // 6. Apply any custom stabilization
    if (options.customStabilization) {
      await options.customStabilization(page);
      preparationSteps.push('custom_stabilization_applied');
    }

    const preparationTime = Date.now() - startTime;

    return {
      success: true,
      preparationSteps,
      preparationTime,
      dynamicRegions,
      ignoreRegions,
      metadata: {
        url,
        viewport: await page.viewportSize(),
        timestamp: new Date().toISOString()
      }
    };
  }

  async stabilizeDynamicContent(page, selectors = []) {
    const stabilizationPromises = [];

    // Apply default stabilization strategies
    stabilizationPromises.push(
      this.freezeTimers(page),
      this.mockLiveData(page),
      this.hideNotifications(page),
      this.stopAnimations(page)
    );

    // Apply selector-specific stabilization
    for (const selector of [...this.config.defaultIgnoreSelectors, ...selectors]) {
      stabilizationPromises.push(
        this.stabilizeSelector(page, selector)
      );
    }

    await Promise.all(stabilizationPromises);

    // Wait for any remaining animations/transitions
    await page.waitForTimeout(1000);
  }

  async detectDynamicRegions(page) {
    const dynamicRegions = [];

    // Method 1: Detect via data attributes
    const attributeElements = await page.$$('[data-dynamic], [data-visual-ignore]');
    for (const element of attributeElements) {
      const region = await this.getElementRegion(element);
      dynamicRegions.push({
        ...region,
        detectionMethod: 'data_attribute',
        selector: await this.getElementSelector(element)
      });
    }

    // Method 2: Detect via content patterns
    if (this.config.autoDetectDynamicContent) {
      const textContent = await page.textContent('body');
      const lines = textContent.split('\n');

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        for (const pattern of this.dynamicPatterns) {
          for (const regex of pattern.patterns) {
            if (regex.test(line)) {
              // Find element containing this text
              const elements = await page.$$(`:has-text("${this.escapeText(line)}")`);
              for (const element of elements) {
                const region = await this.getElementRegion(element);
                dynamicRegions.push({
                  ...region,
                  detectionMethod: 'content_pattern',
                  patternType: pattern.type,
                  matchedPattern: regex.toString(),
                  matchedText: line.substring(0, 50)
                });
              }
              break;
            }
          }
        }
      }
    }

    // Method 3: AI-powered detection (if enabled)
    if (this.config.useAIForDetection) {
      const aiDetected = await this.detectDynamicWithAI(page);
      dynamicRegions.push(...aiDetected);
    }

    // Merge overlapping regions
    return this.mergeOverlappingRegions(dynamicRegions);
  }

  async calculateIgnoreRegions(page, dynamicRegions) {
    const ignoreRegions = [];

    // Add dynamic regions as ignore regions
    dynamicRegions.forEach(region => {
      ignoreRegions.push({
        x: region.x,
        y: region.y,
        width: region.width,
        height: region.height,
        type: 'ignore',
        reason: region.detectionMethod,
        metadata: region
      });
    });

    // Add floating regions for elements that might move slightly
    const floatingElements = await page.$$('[data-floating], .tooltip, .dropdown, .notification');
    for (const element of floatingElements) {
      const region = await this.getElementRegion(element);
      ignoreRegions.push({
        ...region,
        type: 'floating',
        tolerance: 10, // pixels
        reason: 'floating_element'
      });
    }

    // Cache for future use
    const pageUrl = page.url();
    this.ignoreRegionsCache.set(pageUrl, {
      regions: ignoreRegions,
      timestamp: Date.now()
    });

    return ignoreRegions;
  }

  async waitForVisualStability(page, timeout = 10000) {
    const startTime = Date.now();
    let lastScreenshot = null;
    let stableCount = 0;

    while (Date.now() - startTime < timeout && stableCount < 3) {
      const currentScreenshot = await page.screenshot({
        type: 'png',
        encoding: 'binary'
      });

      if (lastScreenshot) {
        const difference = await this.compareScreenshots(lastScreenshot, currentScreenshot);

        if (difference < 0.001) { // Less than 0.1% difference
          stableCount++;
        } else {
          stableCount = 0;
        }
      }

      lastScreenshot = currentScreenshot;
      await page.waitForTimeout(500);
    }

    return stableCount >= 3;
  }

  // Stabilization methods
  async freezeTimers(page) {
    await page.evaluate(() => {
      // Override Date to return fixed time
      const originalDate = Date;
      const fixedTime = new Date('2024-01-01T12:00:00Z').getTime();

      window.__visualTestFixedDate = new Date(fixedTime);

      // Override Date constructor
      Date = class extends originalDate {
        constructor(...args) {
          if (args.length === 0) {
            super(fixedTime);
          } else {
            super(...args);
          }
        }

        static now() {
          return fixedTime;
        }
      };

      // Override performance.now()
      const originalPerformanceNow = performance.now;
      let performanceTime = 0;
      performance.now = () => performanceTime;

      // Stop all intervals and timeouts
      const maxId = setTimeout(() => {}, 0);
      for (let i = 0; i < maxId; i++) {
        clearTimeout(i);
        clearInterval(i);
      }

      console.log('Timers frozen for visual testing');
    });
  }

  async mockLiveData(page) {
    await page.evaluate(() => {
      // Mock common live data elements
      const mockData = {
        stockPrices: {
          'AAPL': '182.63',
          'GOOGL': '138.21',
          'MSFT': '374.51'
        },
        exchangeRates: {
          'USD': '1.00',
          'EUR': '0.92',
          'GBP': '0.79'
        },
        weather: {
          temp: '72°F',
          condition: 'Sunny',
          location: 'San Francisco, CA'
        }
      };

      // Find and replace live data elements
      const elements = document.querySelectorAll('[data-live], .live-data, .stock-price, .exchange-rate');
      elements.forEach(element => {
        const text = element.textContent;

        // Mock stock prices
        if (text.includes('$') && (text.includes('stock') || text.includes('price'))) {
          element.textContent = '$182.63'; // Example fixed price
        }

        // Mock timestamps
        if (text.match(/\d{1,2}:\d{2}/)) {
          element.textContent = '12:00 PM';
        }
      });
    });
  }

  async hideNotifications(page) {
    await page.addStyleTag({
      content: `
        .notification, 
        .toast, 
        .alert, 
        .popup, 
        .cookie-banner {
          display: none !important;
        }

        [data-notification], 
        [aria-live="assertive"], 
        [aria-live="polite"] {
          visibility: hidden !important;
          height: 0 !important;
          overflow: hidden !important;
        }
      `
    });
  }

  async stopAnimations(page) {
    await page.addStyleTag({
      content: `
        *, *::before, *::after {
          animation-delay: -1s !important;
          animation-duration: 1ms !important;
          animation-iteration-count: 1 !important;
          transition-duration: 1ms !important;
          transition-delay: -1s !important;
          animation-play-state: paused !important;
          transition-play-state: paused !important;
        }
      `
    });
  }

  async stabilizeSelector(page, selector) {
    try {
      const elements = await page.$$(selector);

      for (const element of elements) {
        // Try different stabilization methods based on element type
        const tagName = await element.evaluate(el => el.tagName.toLowerCase());

        switch (tagName) {
          case 'input':
          case 'textarea':
            await element.evaluate(el => {
              el.value = el.value || 'test_value';
              el.setAttribute('data-stabilized', 'true');
            });
            break;

          case 'img':
          case 'video':
            await element.evaluate(el => {
              el.style.opacity = '1';
              el.style.filter = 'none';
              el.setAttribute('data-stabilized', 'true');
            });
            break;

          default:
            await element.evaluate(el => {
              el.style.animation = 'none';
              el.style.transition = 'none';
              el.setAttribute('data-stabilized', 'true');
            });
        }
      }
    } catch (error) {
      // Selector might not exist, that's okay
      console.debug(`Selector ${selector} not found for stabilization`);
    }
  }

  // Utility methods
  async getElementRegion(element) {
    const boundingBox = await element.boundingBox();
    if (!boundingBox) return null;

    return {
      x: Math.floor(boundingBox.x),
      y: Math.floor(boundingBox.y),
      width: Math.ceil(boundingBox.width),
      height: Math.ceil(boundingBox.height)
    };
  }

  async getElementSelector(element) {
    return await element.evaluate(el => {
      // Generate a unique selector for the element
      if (el.id) return `#${el.id}`;

      const classes = Array.from(el.classList).join('.');
      if (classes) return `${el.tagName.toLowerCase()}.${classes}`;

      return el.tagName.toLowerCase();
    });
  }

  mergeOverlappingRegions(regions) {
    if (regions.length <= 1) return regions;

    const merged = [];
    let changed = true;

    while (changed) {
      changed = false;
      const remaining = [...regions];

      while (remaining.length > 0) {
        const current = remaining.shift();
        let mergedCurrent = false;

        for (let i = 0; i < merged.length; i++) {
          if (this.regionsOverlap(current, merged[i])) {
            merged[i] = this.combineRegions(merged[i], current);
            mergedCurrent = true;
            changed = true;
            break;
          }
        }

        if (!mergedCurrent) {
          merged.push(current);
        }
      }

      regions = [...merged];
      merged.length = 0;
    }

    return regions;
  }

  regionsOverlap(region1, region2) {
    return !(
      region1.x + region1.width < region2.x ||
      region2.x + region2.width < region1.x ||
      region1.y + region1.height < region2.y ||
      region2.y + region2.height < region1.y
    );
  }

  combineRegions(region1, region2) {
    const x1 = Math.min(region1.x, region2.x);
    const y1 = Math.min(region1.y, region2.y);
    const x2 = Math.max(region1.x + region1.width, region2.x + region2.width);
    const y2 = Math.max(region1.y + region1.height, region2.y + region2.height);

    return {
      x: x1,
      y: y1,
      width: x2 - x1,
      height: y2 - y1,
      sources: [...(region1.sources || [region1]), ...(region2.sources || [region2])]
    };
  }

  escapeText(text) {
    return text.replace(/[\[\](){}*+?.^$|]/g, '\\$&');
  }

  async compareScreenshots(image1, image2) {
    // Simple pixel comparison using pixelmatch
    const PNG = require('pngjs').PNG;
    const pixelmatch = require('pixelmatch');

    const img1 = PNG.sync.read(image1);
    const img2 = PNG.sync.read(image2);

    const diff = new PNG({ width: img1.width, height: img1.height });
    const mismatchedPixels = pixelmatch(
      img1.data, img2.data, diff.data, 
      img1.width, img1.height, { threshold: 0.1 }
    );

    return mismatchedPixels / (img1.width * img1.height);
  }
}

// Integration with visual testing frameworks
export async function createStableVisualTest(page, url, testName, options = {}) {
  const handler = new DynamicContentHandler({
    autoDetectDynamicContent: true,
    useAIForDetection: options.useAI || false
  });

  try {
    // Prepare page for visual testing
    const preparation = await handler.preparePageForVisualTest(page, url, {
      stabilizationSelectors: options.ignoreSelectors || []
    });

    if (!preparation.success) {
      throw new Error('Failed to stabilize page for visual testing');
    }

    // Take stabilized screenshot
    const screenshot = await page.screenshot({
      type: 'png',
      fullPage: options.fullPage || false,
      omitBackground: options.transparentBackground || false
    });

    return {
      screenshot,
      preparation,
      metadata: {
        testName,
        url,
        timestamp: new Date().toISOString(),
        ignoreRegions: preparation.ignoreRegions
      }
    };

  } catch (error) {
    console.error('Failed to create stable visual test:', error);
    throw error;
  }
}

