// accessibility-visual-integration.js
// Comprehensive framework combining visual testing with accessibility validation

class AccessibilityVisualValidator {
  constructor(config = {}) {
    this.config = {
      wcagVersion: '2.1',
      complianceLevel: 'AA',
      enableColorContrastCheck: true,
      enableFocusIndicatorCheck: true,
      enableTextSizeCheck: true,
      enableLayoutAnalysis: true,
      contrastThreshold: 4.5, // WCAG AA minimum
      textSizeThreshold: 16, // pixels minimum for normal text
      ...config
    };

    this.accessibilityRules = this.initializeWCAGRules();
    this.visualAnalyzers = this.initializeAnalyzers();
  }

  initializeWCAGRules() {
    return {
      '1.4.3': {
        id: '1.4.3',
        name: 'Contrast (Minimum)',
        description: 'Text and images of text have a contrast ratio of at least 4.5:1',
        level: 'AA',
        check: this.checkColorContrast.bind(this)
      },
      '1.4.4': {
        id: '1.4.4',
        name: 'Resize Text',
        description: 'Text can be resized without assistive technology up to 200 percent',
        level: 'AA',
        check: this.checkTextResize.bind(this)
      },
      '1.4.10': {
        id: '1.4.10',
        name: 'Reflow',
        description: 'Content can be presented without loss of information or functionality',
        level: 'AA',
        check: this.checkReflow.bind(this)
      },
      '1.4.11': {
        id: '1.4.11',
        name: 'Non-text Contrast',
        description: 'Visual information required to identify UI components has contrast ratio of at least 3:1',
        level: 'AA',
        check: this.checkNonTextContrast.bind(this)
      },
      '2.4.7': {
        id: '2.4.7',
        name: 'Focus Visible',
        description: 'Keyboard focus indicator is visible',
        level: 'AA',
        check: this.checkFocusVisible.bind(this)
      }
    };
  }

  initializeAnalyzers() {
    return {
      colorContrast: new ColorContrastAnalyzer(),
      textAnalyzer: new TextAnalyzer(),
      layoutAnalyzer: new LayoutAnalyzer(),
      focusAnalyzer: new FocusIndicatorAnalyzer()
    };
  }

  async validateScreenshot(screenshot, domSnapshot = null, metadata = {}) {
    const validationStart = Date.now();
    const results = {
      passed: [],
      warnings: [],
      violations: [],
      metadata: {
        timestamp: new Date().toISOString(),
        wcagVersion: this.config.wcagVersion,
        complianceLevel: this.config.complianceLevel,
        ...metadata
      }
    };

    // Analyze screenshot for accessibility issues
    const analyses = await this.analyzeScreenshot(screenshot, domSnapshot);

    // Run WCAG compliance checks
    for (const [ruleId, rule] of Object.entries(this.accessibilityRules)) {
      if (this.shouldCheckRule(rule)) {
        const checkResult = await rule.check(analyses, domSnapshot);

        if (checkResult.passed) {
          results.passed.push({
            ruleId,
            ruleName: rule.name,
            message: checkResult.message
          });
        } else if (checkResult.severity === 'warning') {
          results.warnings.push({
            ruleId,
            ruleName: rule.name,
            message: checkResult.message,
            details: checkResult.details,
            elements: checkResult.elements
          });
        } else {
          results.violations.push({
            ruleId,
            ruleName: rule.name,
            message: checkResult.message,
            details: checkResult.details,
            elements: checkResult.elements,
            severity: checkResult.severity || 'violation',
            screenshotRegion: checkResult.screenshotRegion
          });
        }
      }
    }

    // Generate accessibility score
    results.score = this.calculateAccessibilityScore(results);

    // Generate visual diff with accessibility annotations
    if (results.violations.length > 0) {
      results.annotatedScreenshot = await this.annotateViolations(screenshot, results.violations);
    }

    results.validationTime = Date.now() - validationStart;

    return results;
  }

  async analyzeScreenshot(screenshot, domSnapshot) {
    const analyses = {};

    // Color contrast analysis
    if (this.config.enableColorContrastCheck) {
      analyses.colorContrast = await this.visualAnalyzers.colorContrast.analyze(screenshot, domSnapshot);
    }

    // Text analysis
    if (this.config.enableTextSizeCheck) {
      analyses.text = await this.visualAnalyzers.textAnalyzer.analyze(screenshot);
    }

    // Layout analysis
    if (this.config.enableLayoutAnalysis) {
      analyses.layout = await this.visualAnalyzers.layoutAnalyzer.analyze(screenshot);
    }

    // Focus indicator analysis
    if (this.config.enableFocusIndicatorCheck && domSnapshot) {
      analyses.focus = await this.visualAnalyzers.focusAnalyzer.analyze(screenshot, domSnapshot);
    }

    return analyses;
  }

  // WCAG compliance check implementations
  async checkColorContrast(analyses, domSnapshot) {
    if (!analyses.colorContrast) {
      return { passed: true, message: 'Color contrast check skipped' };
    }

    const lowContrastElements = analyses.colorContrast.elements.filter(
      element => element.contrastRatio < this.config.contrastThreshold
    );

    if (lowContrastElements.length === 0) {
      return {
        passed: true,
        message: `All text elements meet minimum contrast ratio of ${this.config.contrastThreshold}:1`
      };
    }

    return {
      passed: false,
      severity: 'violation',
      message: `${lowContrastElements.length} elements have insufficient color contrast`,
      details: {
        requiredContrast: this.config.contrastThreshold,
        elements: lowContrastElements.map(el => ({
          text: el.text.substring(0, 50),
          foreground: el.foregroundColor,
          background: el.backgroundColor,
          contrastRatio: el.contrastRatio.toFixed(2),
          boundingBox: el.boundingBox
        }))
      }
    };
  }

  async checkTextResize(analyses, domSnapshot) {
    if (!analyses.text) {
      return { passed: true, message: 'Text resize check skipped' };
    }

    const smallTextElements = analyses.text.elements.filter(
      element => element.fontSize < this.config.textSizeThreshold
    );

    if (smallTextElements.length === 0) {
      return {
        passed: true,
        message: `All text elements meet minimum size of ${this.config.textSizeThreshold}px`
      };
    }

    return {
      passed: false,
      severity: 'warning',
      message: `${smallTextElements.length} elements have text smaller than ${this.config.textSizeThreshold}px`,
      details: {
        minimumSize: this.config.textSizeThreshold,
        elements: smallTextElements.map(el => ({
          text: el.text.substring(0, 50),
          fontSize: el.fontSize,
          boundingBox: el.boundingBox
        }))
      }
    };
  }

  async checkFocusVisible(analyses, domSnapshot) {
    if (!analyses.focus || !domSnapshot) {
      return { passed: true, message: 'Focus visible check skipped' };
    }

    const interactiveElements = this.extractInteractiveElements(domSnapshot);
    const elementsWithoutFocus = [];

    for (const element of interactiveElements) {
      const hasFocusIndicator = await this.visualAnalyzers.focusAnalyzer.hasFocusIndicator(
        element,
        analyses.focus
      );

      if (!hasFocusIndicator) {
        elementsWithoutFocus.push({
          selector: element.selector,
          tagName: element.tagName,
          boundingBox: element.boundingBox
        });
      }
    }

    if (elementsWithoutFocus.length === 0) {
      return {
        passed: true,
        message: 'All interactive elements have visible focus indicators'
      };
    }

    return {
      passed: false,
      severity: 'violation',
      message: `${elementsWithoutFocus.length} interactive elements lack visible focus indicators`,
      details: {
        elements: elementsWithoutFocus
      }
    };
  }

  // Utility methods
  shouldCheckRule(rule) {
    // Check if rule applies to configured compliance level
    if (this.config.complianceLevel === 'A' && rule.level === 'AA') {
      return false;
    }

    // Check if specific checks are enabled
    if (rule.id === '1.4.3' && !this.config.enableColorContrastCheck) {
      return false;
    }

    if (rule.id === '2.4.7' && !this.config.enableFocusIndicatorCheck) {
      return false;
    }

    return true;
  }

  calculateAccessibilityScore(results) {
    const totalChecks = results.passed.length + results.warnings.length + results.violations.length;

    if (totalChecks === 0) return 100;

    const violationWeight = 0.7; // Violations reduce score more
    const warningWeight = 0.3; // Warnings reduce score less

    const violationPenalty = (results.violations.length / totalChecks) * violationWeight * 100;
    const warningPenalty = (results.warnings.length / totalChecks) * warningWeight * 100;

    return Math.max(0, 100 - violationPenalty - warningPenalty);
  }

  async annotateViolations(screenshot, violations) {
    // Create annotated screenshot with violation markers
    const PNG = require('pngjs').PNG;
    const png = PNG.sync.read(screenshot);

    // Draw violation markers on screenshot
    violations.forEach((violation, index) => {
      if (violation.screenshotRegion) {
        this.drawViolationMarker(png, violation.screenshotRegion, index + 1);
      }
    });

    return PNG.sync.write(png);
  }

  drawViolationMarker(png, region, number) {
    const { x, y, width, height } = region;
    const color = { r: 255, g: 0, b: 0, a: 200 }; // Semi-transparent red

    // Draw rectangle around violation
    for (let i = x; i < x + width; i++) {
      this.setPixel(png, i, y, color);
      this.setPixel(png, i, y + height - 1, color);
    }

    for (let i = y; i < y + height; i++) {
      this.setPixel(png, x, i, color);
      this.setPixel(png, x + width - 1, i, color);
    }

    // Draw number marker
    this.drawNumber(png, x, y - 10, number, color);
  }

  setPixel(png, x, y, color) {
    if (x >= 0 && x < png.width && y >= 0 && y < png.height) {
      const idx = (png.width * y + x) << 2;
      png.data[idx] = color.r;
      png.data[idx + 1] = color.g;
      png.data[idx + 2] = color.b;
      png.data[idx + 3] = color.a;
    }
  }
}

