export async function runVisualTestWithAccessibility(page, testName, options = {}) {
  const validator = new AccessibilityVisualValidator({
    complianceLevel: options.complianceLevel || 'AA',
    enableColorContrastCheck: true,
    enableFocusIndicatorCheck: true
  });

  // Capture screenshot
  const screenshot = await page.screenshot({
    type: 'png',
    fullPage: options.fullPage || false
  });

  // Capture DOM snapshot for better analysis
  const domSnapshot = await page.evaluate(() => {
    return {
      html: document.documentElement.outerHTML,
      interactiveElements: Array.from(document.querySelectorAll(
        'a, button, input, select, textarea, [tabindex]'
      )).map(el => ({
        tagName: el.tagName,
        id: el.id,
        classes: Array.from(el.classList),
        boundingBox: el.getBoundingClientRect().toJSON()
      }))
    };
  });

  // Run accessibility validation
  const accessibilityResults = await validator.validateScreenshot(
    screenshot,
    domSnapshot,
    {
      testName,
      url: page.url(),
      viewport: await page.viewportSize()
    }
  );

  // Combine with visual test results
  return {
    testName,
    timestamp: new Date().toISOString(),
    screenshot,
    accessibility: accessibilityResults,
    visualTest: await runVisualComparison(screenshot, testName),
    combinedScore: this.calculateCombinedScore(accessibilityResults)
  };
}

