                    "description": "Latency in milliseconds"
                },
                "Jitter": {
                    "type": "String",
                    "default": str(jitter_ms),
                    "description": "Jitter in milliseconds"
                },
                "Duration": {
                    "type": "String",
                    "default": "300",
                    "description": "Duration in seconds"
                }
            },
            "mainSteps": [
                {
                    "name": "InjectLatency",
                    "action": "aws:runShellScript",
                    "inputs": {
                        "runCommand": [
                            "#!/bin/bash",
                            "# Install tc if not present",
                            "command -v tc >/dev/null 2>&1 || { \\",
                            "  if [ -f /etc/redhat-release ]; then",
                            "    yum install -y iproute",
                            "  elif [ -f /etc/debian_version ]; then",
                            "    apt-get update && apt-get install -y iproute2",
                            "  fi",
                            "}",
                            "",
                            "# Get primary network interface",
                            "INTERFACE=$(ip route | grep default | awk '{print $5}')",
                            "",
                            "# Inject latency",
                            "tc qdisc add dev $INTERFACE root netem delay ${Latency}ms ${Jitter}ms",
                            "",
                            "# Wait for duration",
                            "sleep ${Duration}",
                            "",
                            "# Remove latency",
                            "tc qdisc del dev $INTERFACE root"
                        ]
                    }
                }
            ]
        }

        # Create or update SSM document
        document_name = f"InjectNetworkLatency-{int(datetime.now().timestamp())}"
        try:
            self.ssm.create_document(
                Content=json.dumps(ssm_document),
                Name=document_name,
                DocumentType="Command",
                DocumentFormat="JSON"
            )
        except self.ssm.exceptions.DocumentAlreadyExists:
            self.ssm.update_document(
                Content=json.dumps(ssm_document),
                Name=document_name,
                DocumentVersion="$LATEST"
            )

        # Create FIS experiment
        experiment_template = {
            "description": f"Inject {latency_ms}ms network latency with {jitter_ms}ms jitter",
            "stopConditions": [
                {
                    "source": "none"
                }
            ],
            "targets": {
                "InstancesInSubnet": {
                    "resourceType": "aws:ec2:instance",
                    "resourceTags": {
                        "Subnet": "true"
                    },
                    "filters": [
                        {
                            "path": "State.Name",
                            "values": ["running"]
                        }
                    ],
                    "selectionMode": "COUNT(1)"
                }
            },
            "actions": {
                "ssm-latency": {
                    "actionId": "aws:ssm:send-command",
                    "parameters": {
                        "documentArn": f"arn:aws:ssm:{self.region}::document/{document_name}",
                        "documentParameters": json.dumps({
                            "Latency": str(latency_ms),
                            "Jitter": str(jitter_ms),
                            "Duration": "300"
                        }),
                        "duration": "PT5M"
                    },
                    "targets": {
                        "Instances": "InstancesInSubnet"
                    }
                }
            },
            "roleArn": "arn:aws:iam::123456789012:role/awsfis-service-role",
            "tags": {
                "Name": "network-latency-experiment",
                "ChaosType": "network"
            }
        }

        response = self.fis.create_experiment_template(**experiment_template)
        return {
            "template_id": response["experimentTemplate"]["id"],
            "ssm_document": document_name
        }

    def start_experiment(self, template_id: str,
                        client_token: str = None) -> Dict[str, Any]:
        """
        Start a chaos experiment.
        """
        params = {
            "experimentTemplateId": template_id
        }

        if client_token:
            params["clientToken"] = client_token

        response = self.fis.start_experiment(**params)
        experiment_id = response["experiment"]["id"]

        logger.info(f"Started experiment: {experiment_id}")
        return {
            "experiment_id": experiment_id,
            "status": response["experiment"]["state"]["status"],
            "start_time": response["experiment"]["creationTime"]
        }

    def monitor_experiment(self, experiment_id: str) -> Dict[str, Any]:
        """
        Monitor experiment status and results.
        """
        response = self.fis.get_experiment(id=experiment_id)
        experiment = response["experiment"]

        status = experiment["state"]["status"]
        actions = experiment.get("actions", {})

        # Get CloudWatch metrics for impact analysis
        metrics = self._get_experiment_metrics(experiment_id)

        return {
            "experiment_id": experiment_id,
            "status": status,
            "start_time": experiment["creationTime"],
            "end_time": experiment.get("endTime"),
            "actions": actions,
            "metrics": metrics,
            "log": self._get_experiment_logs(experiment_id)
        }

    def stop_experiment(self, experiment_id: str) -> Dict[str, Any]:
        """
        Stop a running experiment.
        """
        response = self.fis.stop_experiment(id=experiment_id)

        logger.info(f"Stopped experiment: {experiment_id}")
        return {
            "experiment_id": experiment_id,
            "status": response["experiment"]["state"]["status"]
        }

