const { expect } = require("chai");
const { ethers } = require("hardhat");

describe("Token Contract", function () {
  let Token;
  let hardhatToken;
  let owner;
  let addr1;
  let addr2;
  let addrs;

  beforeEach(async function () {
    // Deploy a fresh contract for each test
    Token = await ethers.getContractFactory("Token");
    [owner, addr1, addr2, ...addrs] = await ethers.getSigners();
    hardhatToken = await Token.deploy("Test Token", "TT", 1000000);
    await hardhatToken.deployed();
  });

  describe("Deployment", function () {
    it("Should set the right owner", async function () {
      expect(await hardhatToken.owner()).to.equal(owner.address);
    });

    it("Should assign the total supply to the owner", async function () {
      const ownerBalance = await hardhatToken.balanceOf(owner.address);
      expect(await hardhatToken.totalSupply()).to.equal(ownerBalance);
    });

    it("Should have correct name and symbol", async function () {
      expect(await hardhatToken.name()).to.equal("Test Token");
      expect(await hardhatToken.symbol()).to.equal("TT");
    });
  });

  describe("Transactions", function () {
    it("Should transfer tokens between accounts", async function () {
      // Transfer 50 tokens from owner to addr1
      await hardhatToken.transfer(addr1.address, 50);
      expect(await hardhatToken.balanceOf(addr1.address)).to.equal(50);

      // Transfer 50 tokens from addr1 to addr2
      await hardhatToken.connect(addr1).transfer(addr2.address, 50);
      expect(await hardhatToken.balanceOf(addr2.address)).to.equal(50);
      expect(await hardhatToken.balanceOf(addr1.address)).to.equal(0);
    });

    it("Should fail if sender doesn't have enough tokens", async function () {
      const initialOwnerBalance = await hardhatToken.balanceOf(owner.address);

      // Try to send more tokens than owner has
      await expect(
        hardhatToken.connect(addr1).transfer(owner.address, 1)
      ).to.be.revertedWith("ERC20: transfer amount exceeds balance");

      // Owner balance shouldn't have changed
      expect(await hardhatToken.balanceOf(owner.address)).to.equal(initialOwnerBalance);
    });

    it("Should update balances after transfers", async function () {
      const initialOwnerBalance = await hardhatToken.balanceOf(owner.address);

      // Transfer 100 tokens to addr1 and 50 to addr2
      await hardhatToken.transfer(addr1.address, 100);
      await hardhatToken.transfer(addr2.address, 50);

      // Check final balances
      expect(await hardhatToken.balanceOf(owner.address)).to.equal(initialOwnerBalance - 150);
      expect(await hardhatToken.balanceOf(addr1.address)).to.equal(100);
      expect(await hardhatToken.balanceOf(addr2.address)).to.equal(50);
    });
  });

  describe("Gas Optimization", function () {
    it("Should track gas consumption for critical functions", async function () {
      const tx = await hardhatToken.transfer(addr1.address, 100);
      const receipt = await tx.wait();

      console.log(`Transfer gas used: ${receipt.gasUsed.toString()}`);

      // Assert gas usage is within expected bounds
      expect(receipt.gasUsed).to.be.lessThan(100000);
    });
  });
});

