const { ethers } = require("hardhat");
const { performance } = require("perf_hooks");

async function runLoadTest() {
  console.log("Starting blockchain load test...");

  // Deploy test contract
  const LoadTestContract = await ethers.getContractFactory("LoadTestContract");
  const contract = await LoadTestContract.deploy();
  await contract.deployed();

  const [owner, ...users] = await ethers.getSigners();
  const numTransactions = 100;
  const results = {
    totalGas: 0,
    totalTime: 0,
    successful: 0,
    failed: 0,
    gasByFunction: {},
  };

  console.log(`Executing ${numTransactions} transactions...`);

  const startTime = performance.now();

  // Execute batch of transactions
  for (let i = 0; i < numTransactions; i++) {
    const user = users[i % users.length];
    const functionIndex = i % 3;

    try {
      let tx;
      const txStart = performance.now();

      switch (functionIndex) {
        case 0:
          tx = await contract.connect(user).storeData(i, `data-${i}`);
          break;
        case 1:
          tx = await contract.connect(user).updateData(i, `updated-${i}`);
          break;
        case 2:
          tx = await contract.connect(user).complexOperation(i, i * 10);
          break;
      }

      const receipt = await tx.wait();
      const txTime = performance.now() - txStart;

      results.totalGas += receipt.gasUsed.toNumber();
      results.totalTime += txTime;
      results.successful++;

      // Track gas by function
      const functionName = ['storeData', 'updateData', 'complexOperation'][functionIndex];
      if (!results.gasByFunction[functionName]) {
        results.gasByFunction[functionName] = {
          count: 0,
          totalGas: 0,
          avgGas: 0,
        };
      }
      results.gasByFunction[functionName].count++;
      results.gasByFunction[functionName].totalGas += receipt.gasUsed.toNumber();

      // Progress indicator
      if (i % 10 === 0) {
        process.stdout.write(".");
      }
    } catch (error) {
      results.failed++;
      console.log(`\nTransaction ${i} failed:`, error.message);
    }
  }

  const totalTime = performance.now() - startTime;

  // Calculate averages
  results.avgGas = results.totalGas / results.successful;
  results.avgTime = results.totalTime / results.successful;
  results.tps = results.successful / (totalTime / 1000);

  // Calculate gas averages by function
  for (const func in results.gasByFunction) {
    results.gasByFunction[func].avgGas = 
      results.gasByFunction[func].totalGas / results.gasByFunction[func].count;
  }

  console.log("\n\nLoad Test Results:");
  console.log("==================");
  console.log(`Total Transactions: ${numTransactions}`);
  console.log(`Successful: ${results.successful}`);
  console.log(`Failed: ${results.failed}`);
  console.log(`Success Rate: ${((results.successful / numTransactions) * 100).toFixed(2)}%`);
  console.log(`Total Time: ${(totalTime / 1000).toFixed(2)}s`);
  console.log(`Transactions per Second: ${results.tps.toFixed(2)}`);
  console.log(`Average Gas per Transaction: ${results.avgGas.toFixed(0)}`);
  console.log(`Average Time per Transaction: ${results.avgTime.toFixed(2)}ms`);
  console.log(`Total Gas Used: ${results.totalGas}`);

  console.log("\nGas Usage by Function:");
  for (const func in results.gasByFunction) {
    console.log(`  ${func}: ${results.gasByFunction[func].avgGas.toFixed(0)} gas (${results.gasByFunction[func].count} calls)`);
  }

  return results;
}

// Contract definition for reference
const LOAD_TEST_CONTRACT = `
pragma solidity ^0.8.19;

contract LoadTestContract {
    struct Data {
        uint256 id;
        string value;
        uint256 timestamp;
    }

    mapping(uint256 => Data) public dataStore;
    uint256[] public allIds;

    event DataStored(uint256 indexed id, string value, address indexed sender);
    event DataUpdated(uint256 indexed id, string newValue, address indexed sender);

    function storeData(uint256 id, string memory value) external {
        require(dataStore[id].timestamp == 0, "ID already exists");

        dataStore[id] = Data({
            id: id,
            value: value,
            timestamp: block.timestamp
        });

        allIds.push(id);
        emit DataStored(id, value, msg.sender);
    }

    function updateData(uint256 id, string memory newValue) external {
        require(dataStore[id].timestamp > 0, "ID does not exist");

        dataStore[id].value = newValue;
        dataStore[id].timestamp = block.timestamp;

        emit DataUpdated(id, newValue, msg.sender);
    }

    function complexOperation(uint256 id, uint256 multiplier) external returns (uint256) {
        uint256 result = 0;

        // Simulate complex computation
        for (uint256 i = 0; i < 10; i++) {
            result += id * multiplier * (i + 1);
        }

        // Additional storage operations
        if (dataStore[id].timestamp == 0) {
            storeData(id, "generated");
        }

        return result;
    }

    function getAllDataCount() external view returns (uint256) {
        return allIds.length;
    }
}
`;

