const fs = require("fs");
const path = require("path");

class BlockchainTestReporter {
  constructor() {
    this.report = {
      timestamp: new Date().toISOString(),
      summary: {
        totalTests: 0,
        passed: 0,
        failed: 0,
        skipped: 0,
        securityIssues: 0,
        gasOptimizations: [],
      },
      details: {
        unitTests: [],
        integrationTests: [],
        securityTests: [],
        performanceTests: [],
      },
      recommendations: [],
    };
  }

  addTestResult(category, testName, result, details = {}) {
    const testResult = {
      name: testName,
      result: result,
      timestamp: new Date().toISOString(),
      ...details,
    };

    this.report.details[category].push(testResult);

    this.report.summary.totalTests++;
    if (result === "passed") this.report.summary.passed++;
    if (result === "failed") this.report.summary.failed++;
    if (result === "skipped") this.report.summary.skipped++;

    if (details.securityLevel === "high" && result === "failed") {
      this.report.summary.securityIssues++;
    }

    if (details.gasSavings && details.gasSavings > 0) {
      this.report.summary.gasOptimizations.push({
        test: testName,
        savings: details.gasSavings,
      });
    }
  }

  addRecommendation(type, description, priority) {
    this.report.recommendations.push({
      type,
      description,
      priority,
      timestamp: new Date().toISOString(),
    });
  }

  generateReport() {
    // Calculate overall status
    const passRate = (this.report.summary.passed / this.report.summary.totalTests) * 100;
    this.report.summary.passRate = passRate.toFixed(2);

    // Sort recommendations by priority
    this.report.recommendations.sort((a, b) => {
      const priorityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
      return priorityOrder[a.priority] - priorityOrder[b.priority];
    });

    // Calculate total gas savings
    const totalGasSavings = this.report.summary.gasOptimizations.reduce(
      (sum, opt) => sum + opt.savings, 
      0
    );
    this.report.summary.totalGasSavings = totalGasSavings;

    return this.report;
  }

  saveReport(filePath) {
    const report = this.generateReport();
    const jsonReport = JSON.stringify(report, null, 2);

    fs.writeFileSync(filePath, jsonReport, "utf8");

    // Also generate a human-readable summary
    const summary = `
BLOCKCHAIN TEST REPORT
=====================
Timestamp: ${report.timestamp}

SUMMARY
-------
Total Tests: ${report.summary.totalTests}
Passed: ${report.summary.passed} (${report.summary.passRate}%)
Failed: ${report.summary.failed}
Skipped: ${report.summary.skipped}

SECURITY
--------
High-risk Issues: ${report.summary.securityIssues}

GAS OPTIMIZATION
----------------
Total Gas Savings: ${report.summary.totalGasSavings} gas
Number of Optimizations: ${report.summary.gasOptimizations.length}

RECOMMENDATIONS
---------------
${report.recommendations.map(rec => `[${rec.priority.toUpperCase()}] ${rec.type}: ${rec.description}`).join("\n")}

DETAILED RESULTS
----------------
Unit Tests: ${report.details.unitTests.filter(t => t.result === "passed").length}/${report.details.unitTests.length} passed
Integration Tests: ${report.details.integrationTests.filter(t => t.result === "passed").length}/${report.details.integrationTests.length} passed
Security Tests: ${report.details.securityTests.filter(t => t.result === "passed").length}/${report.details.securityTests.length} passed
Performance Tests: ${report.details.performanceTests.filter(t => t.result === "passed").length}/${report.details.performanceTests.length} passed
`;

    const summaryPath = filePath.replace(".json", "-summary.txt");
    fs.writeFileSync(summaryPath, summary, "utf8");

    console.log(`Report saved to ${filePath}`);
    console.log(`Summary saved to ${summaryPath}`);

    return { jsonPath: filePath, summaryPath };
  }
}

